/* Tech 3D · Nivell 2 · unitat 5 «Bucles i patrons» · guia del professorat (p5-1 … p5-4)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1']. Les diapositives «media» mostren el
   programa (amb colors) i el model 3D que en surt (TMEDIA.model); el camp «code» mostra codi per llegir en veu alta. */
Object.assign(TGUIDE, (() => {
  // el codi de les diapositives en català i en castellà (només canvien les paraules del llenguatge)
  const KES = { cub: 'cubo', cilindre: 'cilindro', mou: 'mueve', repeteix: 'repite', uneix: 'une', con: 'cono', tub: 'tubo', pas: 'paso' };
  const CK = s => s + '|' + s.replace(/\b[a-zà-ú]+\b/g, w => KES[w] || w);
  const ROW5 = `repeteix i de 0 a 4 {\n  mou(i * 25, 0, 0) cub(20)\n}`;
  const PEN6 = `cub(120, 16, 4)\nrepeteix i de 0 a 5 {\n  mou(10 + i * 20, 8, 4) cilindre(8, 30)\n}`;
  const PRACK = `n = 6\ndist = 20\ncub(n * dist, 16, 4)\nrepeteix i de 0 a (n - 1) {\n  mou(dist / 2 + i * dist, 8, 4) cilindre(8, 30)\n}`;
  const STAIR = `repeteix i de 0 a 5 {\n  mou(i * 12, 0, 0) cub(12, 30, 8 + i * 8)\n}`;
  const GRID = `repeteix j de 0 a 2 {\n  repeteix i de 0 a 3 {\n    mou(i * 25, j * 25, 0) cub(20)\n  }\n}`;
  const GRAD = `resta {\n  cub(90, 70, 20)\n  repeteix j de 0 a 2 {\n    repeteix i de 0 a 3 {\n      mou(15 + i * 20, 15 + j * 20, 3) cilindre(14, 18)\n    }\n  }\n}`;
  const PASDEMO = `repeteix x de 0 a 60 pas 20 {\n  mou(x, 0, 0) cilindre(10, 15)\n}`;
  const KEYPAD = `cub(74, 96, 6)\nrepeteix j de 0 a 3 {\n  repeteix i de 0 a 2 {\n    mou(6 + i * 22, 6 + j * 22, 6) cub(18, 18, 5)\n  }\n}`;
  const PILES = `nx = 5\nny = 2\nresta {\n  cub(nx * 19 + 6, ny * 19 + 6, 24)\n  repeteix j de 0 a (ny - 1) {\n    repeteix i de 0 a (nx - 1) {\n      mou(12.5 + i * 19, 12.5 + j * 19, 4) cilindre(15, 22)\n    }\n  }\n}`;
  const ORB6 = `n = 6\nrepeteix i de 0 a (n - 1) {\n  gira(0, 0, i * 360 / n) mou(25, 0, 0) cilindre(10, 8)\n}`;
  const CLOCK = `cilindre(80, 4)\nrepeteix i de 0 a 11 {\n  gira(0, 0, i * 30) mou(30, -2, 4) cub(8, 4, 3)\n}`;
  const CLOCKBAD = `cilindre(80, 4)\nrepeteix i de 0 a 11 {\n  mou(30, -2, 4) gira(0, 0, i * 30) cub(8, 4, 3)\n}`;
  const FLOWER = `n = 5\ncilindre(14, 6)\nrepeteix i de 0 a (n - 1) {\n  gira(0, 0, i * 360 / n) mou(14, 0, 0) escala(1.6, 1, 1) cilindre(12, 4)\n}`;
  const WHEEL = `tub(70, 6, 5)\ncilindre(14, 6)\nrepeteix i de 0 a 7 {\n  gira(0, 0, i * 45) mou(0, -2, 0) cub(32, 4, 6)\n}`;
  const GEARB = `cilindre(36, 6)\nrepeteix i de 0 a 11 {\n  gira(0, 0, i * 30) mou(15, -2.25, 0) cub(6, 4.5, 6)\n}`;
  const GEAR12 = `resta {\n  uneix {\n    cilindre(36, 6)\n    repeteix i de 0 a 11 {\n      gira(0, 0, i * 30) mou(15, -2.25, 0) cub(6, 4.5, 6)\n    }\n  }\n  mou(0, 0, -1) cilindre(6, 8)\n}`;
  const GBODY = `resta {\n  uneix {\n    cilindre(d, h)\n    repeteix i de 0 a (z - 1) {\n      gira(0, 0, i * 360 / z) mou(d / 2 - m, -m * 0.75, 0) cub(2 * m, 1.5 * m, h)\n    }\n  }\n  mou(0, 0, -1) cilindre(e, h + 2)\n}`;
  const GV = z => `z = ${z}\nm = 3\nh = 6\ne = 6\nd = m * z\n`;
  const GEARP = GV(12) + GBODY, GEARP20 = GV(20) + GBODY;
  const TWO = `resta {\n  uneix {\n    cilindre(24, 6)\n    repeteix i de 0 a 7 {\n      gira(0, 0, i * 45) mou(9, -2.25, 0) cub(6, 4.5, 6)\n    }\n  }\n  mou(0, 0, -1) cilindre(6, 8)\n}\nmou(36, 0, 0) gira(0, 0, 11.25) resta {\n  uneix {\n    cilindre(48, 6)\n    repeteix i de 0 a 15 {\n      gira(0, 0, i * 22.5) mou(21, -2.25, 0) cub(6, 4.5, 6)\n    }\n  }\n  mou(0, 0, -1) cilindre(6, 8)\n}`;
  return {
  /* ---------- Sessió 1 · Repetir en fila ---------- */
  'p5-1': {
    obj: ["L'alumne/a reconeix un patró de repetició en un programa i l'escriu amb un bucle «repeteix».|El alumno/a reconoce un patrón de repetición en un programa y lo escribe con un bucle «repite».",
      "L'alumne/a calcula quantes vegades es fa un bucle (final − inici + 1) i quins valors pren el comptador.|El alumno/a calcula cuántas veces se hace un bucle (final − inicio + 1) y qué valores toma el contador.",
      "L'alumne/a fa servir el comptador dins de les expressions (posició i × pas, mides que creixen) per fer files i escales.|El alumno/a usa el contador dentro de las expresiones (posición i × paso, medidas que crecen) para hacer filas y escaleras.",
      "L'alumne/a fa una fila paramètrica amb variables i comprova que funciona amb diversos valors.|El alumno/a hace una fila paramétrica con variables y comprueba que funciona con varios valores."],
    comp: ["Tecnologia i digitalització: disseny assistit per ordinador (CAD 3D) amb codi i bucles|Tecnología y digitalización: diseño asistido por ordenador (CAD 3D) con código y bucles",
      "Pensament computacional: reconèixer patrons i generalitzar-los amb estructures de repetició|Pensamiento computacional: reconocer patrones y generalizarlos con estructuras de repetición",
      "Matemàtiques: sentit algebraic (expressions amb una variable) i mesura en mil·límetres|Matemáticas: sentido algebraico (expresiones con una variable) y medida en milímetros",
      "Aprendre a aprendre: predir, comprovar i corregir els errors de «un de més»|Aprender a aprender: predecir, comprobar y corregir los errores de «uno de más»"],
    vocab: [["Bucle|Bucle", "Instrucció que repeteix un bloc d'instruccions diverses vegades.|Instrucción que repite un bloque de instrucciones varias veces."],
      ["Comptador|Contador", "La variable del bucle (i) que canvia a cada volta: 0, 1, 2…|La variable del bucle (i) que cambia en cada vuelta: 0, 1, 2…"],
      ["Iteració (volta)|Iteración (vuelta)", "Cada una de les vegades que es fa el bloc del bucle.|Cada una de las veces que se hace el bloque del bucle."],
      ["Pas|Paso", "La distància entre el centre d'una còpia i el de la següent.|La distancia entre el centro de una copia y el de la siguiente."],
      ["Patró|Patrón", "Una regularitat que es repeteix i que es pot descriure amb una regla.|Una regularidad que se repite y que se puede describir con una regla."],
      ["Error de «un de més»|Error de «uno de más»", "Fer una volta de més o de menys en un bucle, per oblidar que els dos extrems compten.|Dar una vuelta de más o de menos en un bucle, por olvidar que los dos extremos cuentan."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Repetir en fila»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Repetir en fila»", "Projector i la presentació de la sessió|Proyector y la presentación de la sesión", "Per parelles: una tira de paper de 3 × 20 cm, un regle i un llapis|Por parejas: una tira de papel de 3 × 20 cm, una regla y un lápiz"],
      imprimir: ["Fitxa: la tira del bucle (una per parella)|Ficha: la tira del bucle (una por pareja)"],
      prep: ["Retallar les tires de paper (3 × 20 cm), una per parella.|Recortar las tiras de papel (3 × 20 cm), una por pareja.", "Provar el repte del penjador paramètric: cal escriure el final del bucle entre parèntesis, (n - 1).|Probar el reto del colgador paramétrico: hay que escribir el final del bucle entre paréntesis, (n - 1).", "Tenir a la pissarra la fórmula: còpies = final − inici + 1.|Tener en la pizarra la fórmula: copias = final − inicio + 1."] },
    plan: [
      { min: 5, t: "Un encàrrec repetitiu|Un encargo repetitivo", fase: 'inici', fa: "Presenta l'encàrrec del laboratori: un penjador amb 6 pinces iguals. Mostra el programa de quatre línies que només canvien en un número i pregunta què passaria si en volguessin 30.|Presenta el encargo del laboratorio: un colgador con 6 pinzas iguales. Muestra el programa de cuatro líneas que solo cambian en un número y pregunta qué pasaría si quisieran 30.",
        diu: ["Quin número canvia d'una línia a l'altra? Com canvia?|¿Qué número cambia de una línea a otra? ¿Cómo cambia?"], slides: ['s1', 's2'], app: "Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.", org: "Tot el grup|Todo el grupo" },
      { min: 12, t: "El bucle i el comptador|El bucle y el contador", fase: 'teoria', fa: "Explica repeteix amb el comptador i: quins valors pren i per què de 0 a 4 són 5 voltes. Feu junts la taula i → i × 25. Després, el pas, l'espai i la llargada amb el penjador, i la versió amb variables (n i dist), amb el final entre parèntesis.|Explica repite con el contador i: qué valores toma i y por qué de 0 a 4 son 5 vueltas. Haced juntos la tabla i → i × 25. Después, el paso, el espacio y la longitud con el colgador, y la versión con variables (n y dist), con el final entre paréntesis.",
        diu: ["Si el bucle va de 0 a 4, quantes voltes fa? I de 1 a 4?|Si el bucle va de 0 a 4, ¿cuántas vueltas da? ¿Y de 1 a 4?", "6 pinces: quants espais hi ha entre elles?|6 pinzas: ¿cuántos espacios hay entre ellas?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: "Tot el grup|Todo el grupo" },
      { min: 10, t: "La tira del bucle|La tira del bucle", fase: 'desconnectat', fa: "Per parelles: omplen la taula de la fitxa (on comença i on acaba cada cub) i dibuixen els cubs a la tira amb el regle, en mil·límetres reals. Mesuren la llargada total i la comparen amb el càlcul (5 × 15 + 10 = 85 mm).|Por parejas: rellenan la tabla de la ficha (dónde empieza y dónde acaba cada cubo) y dibujan los cubos en la tira con la regla, en milímetros reales. Miden la longitud total y la comparan con el cálculo (5 × 15 + 10 = 85 mm).",
        diu: ["Abans de dibuixar: quants cubs i quants espais hi haurà?|Antes de dibujar: ¿cuántos cubos y cuántos espacios habrá?"], slides: ['s8'], app: "Encara no: fitxa, tira i regle.|Todavía no: ficha, tira y regla.", org: "Per parelles|Por parejas" },
      { min: 22, t: "A l'ordinador: files i escales|En el ordenador: filas y escaleras", fase: 'ordinador', fa: "Fan la sessió a l'app: prediccions, dos errors per trobar i els reptes (fila de cubs, penjador, escala i penjador paramètric). Passa per les taules al penjador paramètric: que expliquin per què la base fa n × dist i on va la primera pinça.|Hacen la sesión en la app: predicciones, dos errores para encontrar y los retos (fila de cubos, colgador, escalera y colgador paramétrico). Pasa por las mesas en el colgador paramétrico: que expliquen por qué la base mide n × dist y dónde va la primera pinza.",
        diu: ["Quant val i a la tercera volta? On queda aquell cub?|¿Cuánto vale i en la tercera vuelta? ¿Dónde queda ese cubo?", "Canvia n per 3 i per 9: continua funcionant?|Cambia n por 3 y por 9: ¿sigue funcionando?"], slides: ['s9', 's10', 's11', 's12'], app: "Sessió «Repetir en fila», fins al disseny lliure.|Sesión «Repetir en fila», hasta el diseño libre.", org: "Individual|Individual" },
      { min: 6, t: "La meva fila|Mi fila", fase: 'crea', fa: "Disseny lliure amb un bucle: penjador de claus, porta-pinzells, pont amb pilars, xilòfon… Ha de ser una sola peça que toqui la placa. Es desa a «Projectes».|Diseño libre con un bucle: colgador de llaves, portapinceles, puente con pilares, xilófono… Tiene que ser una sola pieza que toque la placa. Se guarda en «Proyectos».",
        diu: ["Les còpies toquen la base? Si no, el model tindrà trossos solts.|¿Las copias tocan la base? Si no, el modelo tendrá trozos sueltos."], slides: ['s13'], app: "Pas «Dissenya una peça amb una fila».|Paso «Diseña una pieza con una fila».", org: "Individual|Individual" },
      { min: 5, t: "Tancament|Cierre", fase: 'tancament', fa: "Repassa les tres idees clau i el tiquet de sortida.|Repasa las tres ideas clave y el ticket de salida.", diu: ["Quantes voltes fa repeteix i de 0 a 7? Quant fa de llarg una fila de 4 cubs de 10 amb pas 15?|¿Cuántas vueltas da repite i de 0 a 7? ¿Cuánto mide de largo una fila de 4 cubos de 10 con paso 15?"], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: "Tot el grup|Todo el grupo" }
    ],
    errors: [["Escriu de 0 a 6 per fer 6 còpies i en surten 7.|Escribe de 0 a 6 para hacer 6 copias y salen 7.", "Que compti en veu alta els valors de i (0, 1, 2…) amb els dits. Recorda la fórmula final − inici + 1.|Que cuente en voz alta los valores de i (0, 1, 2…) con los dedos. Recuerda la fórmula final − inicio + 1."],
      ["Totes les còpies surten al mateix lloc.|Todas las copias salen en el mismo sitio.", "El mou no fa servir i. Pregunta-li: què canvia d'una volta a l'altra? Si res no depèn de i, totes les còpies són idèntiques i al mateix lloc.|El mueve no usa i. Pregúntale: ¿qué cambia de una vuelta a otra? Si nada depende de i, todas las copias son idénticas y en el mismo sitio."],
      ["Escriu repeteix i de 0 a n - 1 i surt un error a la línia.|Escribe repite i de 0 a n - 1 y sale un error en la línea.", "Si el final és un càlcul amb variables, va entre parèntesis: repeteix i de 0 a (n - 1). Així el programa sap on acaba el número.|Si el final es un cálculo con variables, va entre paréntesis: repite i de 0 a (n - 1). Así el programa sabe dónde acaba el número."]],
    diff: { mes: "Fer el repte ⭐ de la tanca de l'hort (dos bucles seguits) i, després, convertir-la en paramètrica: n pals i travesses de (n − 1) × 15 + 4 mm.|Hacer el reto ⭐ de la valla del huerto (dos bucles seguidos) y, después, convertirla en paramétrica: n postes y travesaños de (n − 1) × 15 + 4 mm.",
      menys: "Fer primer la taula de valors de i a la llibreta abans de cada repte i treballar amb blocs. Al penjador paramètric, donar-li la línia del cilindre escrita.|Hacer primero la tabla de valores de i en la libreta antes de cada reto y trabajar con bloques. En el colgador paramétrico, darle la línea del cilindro escrita." },
    aval: { ticket: ["Quantes voltes fa repeteix i de 0 a 7?|¿Cuántas vueltas da repite i de 0 a 7?", "Escriu un bucle que faci 4 cilindres en fila separats 30 mm.|Escribe un bucle que haga 4 cilindros en fila separados 30 mm."],
      rubric: [["Comptar voltes|Contar vueltas", "Calcula les voltes i els valors de i sense provar.|Calcula las vueltas y los valores de i sin probar.", "Ho troba provant, o s'equivoca en una volta.|Lo encuentra probando, o se equivoca en una vuelta."],
        ["Fer servir el comptador|Usar el contador", "Posa i a la posició i a les mides segons el patró.|Pone i en la posición y en las medidas según el patrón.", "Fa la fila però amb números fixos o amb ajuda.|Hace la fila pero con números fijos o con ayuda."],
        ["Fila paramètrica|Fila paramétrica", "El penjador funciona amb qualsevol n i ho explica.|El colgador funciona con cualquier n y lo explica.", "Funciona amb un sol valor de n.|Funciona con un solo valor de n."]] },
    casa: "Busca a casa un objecte amb peces iguals repetides en fila (una pinta, un radiador, una persiana, un teclat…). Mesura el pas i escriu el bucle que el faria.|Busca en casa un objeto con piezas iguales repetidas en fila (un peine, un radiador, una persiana, un teclado…). Mide el paso y escribe el bucle que lo haría.",
    intro: "Primera sessió de bucles: l'alumnat passa d'escriure cada peça a descriure la regla que les genera totes. El més important és el comptador: que entenguin que i pren valors i que es pot fer servir en qualsevol càlcul.|Primera sesión de bucles: el alumnado pasa de escribir cada pieza a describir la regla que las genera todas. Lo más importante es el contador: que entiendan que i toma valores y que se puede usar en cualquier cálculo.",
    claus: ["repeteix i de 0 a 4 fa 5 voltes: els dos extrems compten.|repite i de 0 a 4 da 5 vueltas: los dos extremos cuentan.", "El comptador i es pot fer servir dins de qualsevol expressió: posició, mida, alçada.|El contador i se puede usar dentro de cualquier expresión: posición, medida, altura.", "Llargada d'una fila = (còpies − 1) × pas + amplada d'una peça.|Longitud de una fila = (copias − 1) × paso + anchura de una pieza.", "Si el final del bucle és un càlcul amb variables, va entre parèntesis.|Si el final del bucle es un cálculo con variables, va entre paréntesis."],
    prev: ["Saber fer servir variables i expressions (unitat 4).|Saber usar variables y expresiones (unidad 4).", "Conèixer cub, cilindre i mou.|Conocer cubo, cilindro y mueve.", "Saber mesurar en mil·límetres amb el regle.|Saber medir en milímetros con la regla."],
    faq: [["Per què el comptador comença a 0 i no a 1?|¿Por qué el contador empieza en 0 y no en 1?", "Perquè així la primera còpia queda a l'origen (0 × pas = 0). Es pot començar a 1, però llavors la primera còpia ja surt desplaçada un pas.|Porque así la primera copia queda en el origen (0 × paso = 0). Se puede empezar en 1, pero entonces la primera copia ya sale desplazada un paso."],
      ["Es pot dir d'una altra manera el comptador, en lloc de i?|¿Se puede llamar de otra manera al contador, en lugar de i?", "Sí: qualsevol nom que no sigui una paraula del llenguatge (k, pinça, n…). La i és una tradició de la programació i de les matemàtiques.|Sí: cualquier nombre que no sea una palabra del lenguaje (k, pinza, n…). La i es una tradición de la programación y de las matemáticas."],
      ["Quantes còpies puc fer com a molt?|¿Cuántas copias puedo hacer como mucho?", "El taller deixa fer fins a 400 peces i 10.000 voltes. Si en demanes més, surt un avís amable per revisar el bucle.|El taller deja hacer hasta 400 piezas y 10.000 vueltas. Si pides más, sale un aviso amable para revisar el bucle."]],
    tec: [["Surt «aquí hi falta un número o una variable» a la línia del repeteix.|Sale «aquí falta un número o una variable» en la línea del repite.", "El final del bucle té una variable sense parèntesis. Escriviu-lo així: repeteix i de 0 a (n - 1).|El final del bucle tiene una variable sin paréntesis. Escribidlo así: repite i de 0 a (n - 1)."],
      ["El cub nou queda fora del bucle.|El cubo nuevo queda fuera del bucle.", "Els blocs nous van on hi ha la ratlla «els blocs nous van aquí». Toqueu la ratlla de dins del repeteix abans d'afegir-lo, o moveu-lo amb les fletxes.|Los bloques nuevos van donde está la raya «los bloques nuevos van aquí». Tocad la raya de dentro del repite antes de añadirlo, o movedlo con las flechas."],
      ["El 3D va lent amb molts cubs.|El 3D va lento con muchos cubos.", "És normal amb centenars de peces. Reduïu el nombre de voltes mentre proveu i augmenteu-lo al final.|Es normal con cientos de piezas. Reducid el número de vueltas mientras probáis y aumentadlo al final."]],
    extra: ["Fer una escala que puja i baixa (piràmide) amb dos bucles seguits.|Hacer una escalera que sube y baja (pirámide) con dos bucles seguidos.", "Fer un xilòfon amb barres que s'escurcen: cub(10, 80 - i * 6, 6).|Hacer un xilófono con barras que se acortan: cubo(10, 80 - i * 6, 6).", "Exportar el penjador a .scad i comparar el bucle amb el for d'OpenSCAD.|Exportar el colgador a .scad y comparar el bucle con el for de OpenSCAD."],
    trans: ["Sessió següent: graelles amb bucles niats.|Sesión siguiente: rejillas con bucles anidados.", "Matemàtiques: sèries numèriques i expressions algebraiques (termes d'una progressió aritmètica).|Matemáticas: series numéricas y expresiones algebraicas (términos de una progresión aritmética)."],
    slides: [
      { id: 's1', k: 'portada', t: 'Repetir en fila|Repetir en fila', x: "Bucles: el programa repeteix per tu|Bucles: el programa repite por ti", nota: "Presenta l'encàrrec del laboratori: el penjador de 6 bates.|Presenta el encargo del laboratorio: el colgador de 6 batas." },
      { id: 's2', k: 'pregunta', t: "Què es repeteix?|¿Qué se repite?", x: "Quatre línies gairebé iguals. Què canvia? I si en volguéssim 30?|Cuatro líneas casi iguales. ¿Qué cambia? ¿Y si quisiéramos 30?", code: CK(`cub(20)\nmou(25, 0, 0) cub(20)\nmou(50, 0, 0) cub(20)\nmou(75, 0, 0) cub(20)`), nota: "Busquem que diguin «canvia la x, de 25 en 25».|Buscamos que digan «cambia la x, de 25 en 25»." },
      { id: 's3', k: 'anim', t: 'De quatre línies a un bucle|De cuatro líneas a un bucle', anim: 'p5copy', nota: "Fes notar que el número que canvia passa a ser i * 25.|Haz notar que el número que cambia pasa a ser i * 25." },
      { id: 's4', k: 'media', t: 'repeteix i de 0 a 4 { … }|repite i de 0 a 4 { … }', media: { k: 'model', prog: ROW5 }, nota: "Abans de mirar el model: quants cubs sortiran? 4 − 0 + 1 = 5.|Antes de mirar el modelo: ¿cuántos cubos saldrán? 4 − 0 + 1 = 5." },
      { id: 's5', k: 'anim', t: 'El comptador i|El contador i', anim: 'p5count', x: "Posició = i × pas|Posición = i × paso", nota: "Feu la taula en veu alta: i = 0 → 0, i = 1 → 25…|Haced la tabla en voz alta: i = 0 → 0, i = 1 → 25…" },
      { id: 's6', k: 'media', t: "El penjador: pas, espai i llargada|El colgador: paso, espacio y longitud", media: { k: 'model', prog: PEN6 }, nota: "Pas 20, espai 12 (20 − 8), 6 pinces i 5 espais. La base fa 120 mm.|Paso 20, espacio 12 (20 − 8), 6 pinzas y 5 espacios. La base mide 120 mm." },
      { id: 's7', k: 'media', t: 'Un bucle amb variables|Un bucle con variables', media: { k: 'model', prog: PRACK }, nota: "Insisteix en els parèntesis: repeteix i de 0 a (n - 1). Pregunta què passaria amb de 0 a n.|Insiste en los paréntesis: repite i de 0 a (n - 1). Pregunta qué pasaría con de 0 a n." },
      { id: 's8', k: 'activitat', t: 'La tira del bucle|La tira del bucle', timer: 8, punts: ["Ompliu la taula de la fitxa: on comença i on acaba cada cub.|Rellenad la tabla de la ficha: dónde empieza y dónde acaba cada cubo.", "Dibuixeu els cubs a la tira, en mil·límetres.|Dibujad los cubos en la tira, en milímetros.", "Mesureu i compareu amb el càlcul: 85 mm.|Medid y comparad con el cálculo: 85 mm."], nota: "Per parelles. Qui acabi, que faci l'exercici 3 de la fitxa (de 1 a 4).|Por parejas. Quien acabe, que haga el ejercicio 3 de la ficha (de 1 a 4)." },
      { id: 's9', k: 'pregunta', t: 'Prediu: quin model fa?|Predice: ¿qué modelo hace?', code: CK(`repeteix i de 0 a 3 {\n  mou(i * 15, 0, 0) cub(15, 20, 10 + i * 10)\n}`), nota: "Una escala que puja: alçades 10, 20, 30 i 40 mm.|Una escalera que sube: alturas 10, 20, 30 y 40 mm." },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ["Prediu i troba els errors.|Predice y encuentra los errores.", "Fila de cubs, penjador i escala.|Fila de cubos, colgador y escalera.", "El penjador paramètric (n pinces).|El colgador paramétrico (n pinzas)."], nota: "Recorda: primer pensa quant val i a cada volta.|Recuerda: primero piensa cuánto vale i en cada vuelta." },
      { id: 's11', k: 'media', t: "L'escala|La escalera", media: { k: 'model', prog: STAIR }, nota: "Per a qui s'encalli: el comptador va a la posició (i * 12) i a l'alçada (8 + i * 8).|Para quien se atasque: el contador va a la posición (i * 12) y a la altura (8 + i * 8)." },
      { id: 's12', k: 'concepte', t: "Dues errades típiques|Dos errores típicos", punts: ["De 0 a 6 fa 7 voltes, no 6.|De 0 a 6 da 7 vueltas, no 6.", "Si el mou no té i, totes les còpies queden al mateix lloc.|Si el mueve no tiene i, todas las copias quedan en el mismo sitio."], code: CK(`repeteix i de 0 a 5 {\n  mou(10 + i * 20, 8, 4) cilindre(8, 30)\n}`), nota: "Són els dos errors que trobaran a l'app.|Son los dos errores que encontrarán en la app." },
      { id: 's13', k: 'repte', t: 'La meva fila|Mi fila', punts: ["Fes servir un bucle.|Usa un bucle.", "Almenys 4 còpies.|Al menos 4 copias.", "Una sola peça que toca la placa.|Una sola pieza que toca la placa."], nota: "Idees: penjador de claus, pont, xilòfon, porta-pinzells.|Ideas: colgador de llaves, puente, xilófono, portapinceles." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["repeteix i de 0 a 4 fa 5 voltes.|repite i de 0 a 4 da 5 vueltas.", "El comptador va dins dels càlculs: i × pas.|El contador va dentro de los cálculos: i × paso.", "Llargada = (còpies − 1) × pas + amplada.|Longitud = (copias − 1) × paso + anchura."], nota: "Llegiu-ho junts.|Leedlo juntos." },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Quantes voltes fa repeteix i de 0 a 7?|¿Cuántas vueltas da repite i de 0 a 7?", "Escriu un bucle de 4 cilindres separats 30 mm.|Escribe un bucle de 4 cilindros separados 30 mm."], nota: "En un paper, abans de sortir.|En un papel, antes de salir." }
    ],
    print: [{ id: 'p1', t: 'Fitxa: la tira del bucle|Ficha: la tira del bucle', k: 'fitxa', intro: "Llegeix cada bucle, omple la taula i dibuixa'l a la tira. Les mesures són en mil·límetres.|Lee cada bucle, rellena la tabla y dibújalo en la tira. Las medidas son en milímetros.",
      items: [{ q: "<code>repeteix i de 0 a 5 { mou(i * 15, 0, 0) cub(10) }</code><br>Per a cada i, on comença i on acaba el cub? Quants cubs i quants espais hi ha?|<code>repite i de 0 a 5 { mueve(i * 15, 0, 0) cubo(10) }</code><br>Para cada i, ¿dónde empieza y dónde acaba el cubo? ¿Cuántos cubos y cuántos espacios hay?", big: true, sol: "6 cubs i 5 espais de 5 mm: 0–10, 15–25, 30–40, 45–55, 60–70 i 75–85.|6 cubos y 5 espacios de 5 mm: 0–10, 15–25, 30–40, 45–55, 60–70 y 75–85." },
        { q: "Quant fa de llarg la fila de l'exercici 1? Comprova-ho amb la fórmula (còpies − 1) × pas + amplada.|¿Cuánto mide de largo la fila del ejercicio 1? Compruébalo con la fórmula (copias − 1) × paso + anchura.", sol: "(6 − 1) × 15 + 10 = 85 mm.|(6 − 1) × 15 + 10 = 85 mm." },
        { q: "<code>repeteix i de 1 a 4 { mou(i * 20, 0, 0) cub(10) }</code>: quantes voltes fa i on queda el primer cub?|<code>repite i de 1 a 4 { mueve(i * 20, 0, 0) cubo(10) }</code>: ¿cuántas vueltas da y dónde queda el primer cubo?", sol: "4 voltes (4 − 1 + 1). El primer cub és a x = 20, no a l'origen.|4 vueltas (4 − 1 + 1). El primer cubo está en x = 20, no en el origen." },
        { q: "Escriu el bucle d'una tanca de 8 pals de 4 mm amb un pas de 12 mm. Quant farà de llarg?|Escribe el bucle de una valla de 8 postes de 4 mm con un paso de 12 mm. ¿Cuánto medirá de largo?", sol: "repeteix i de 0 a 7 { mou(i * 12, 0, 0) cub(4, 4, 30) }. Llargada: 7 × 12 + 4 = 88 mm.|repite i de 0 a 7 { mueve(i * 12, 0, 0) cubo(4, 4, 30) }. Longitud: 7 × 12 + 4 = 88 mm." }] }]
  },
  /* ---------- Sessió 2 · Graelles ---------- */
  'p5-2': {
    obj: ["L'alumne/a explica com funcionen dos bucles niats i en calcula el nombre de voltes (files × columnes).|El alumno/a explica cómo funcionan dos bucles anidados y calcula su número de vueltas (filas × columnas).",
      "L'alumne/a fa graelles en el pla xy (i també en altres plans) amb dos comptadors diferents.|El alumno/a hace rejillas en el plano xy (y también en otros planos) con dos contadores distintos.",
      "L'alumne/a combina una graella amb resta per foradar una placa amb molts forats iguals, amb marges correctes.|El alumno/a combina una rejilla con resta para agujerear una placa con muchos agujeros iguales, con márgenes correctos.",
      "L'alumne/a fa una graella paramètrica (nx × ny) on la placa i els forats s'adapten a les variables.|El alumno/a hace una rejilla paramétrica (nx × ny) donde la placa y los agujeros se adaptan a las variables."],
    comp: ["Tecnologia i digitalització: CAD 3D d'objectes funcionals (gradeta, organitzador) a partir d'especificacions|Tecnología y digitalización: CAD 3D de objetos funcionales (gradilla, organizador) a partir de especificaciones",
      "Pensament computacional: estructures de repetició niades i descomposició del problema en files i columnes|Pensamiento computacional: estructuras de repetición anidadas y descomposición del problema en filas y columnas",
      "Matemàtiques: multiplicació com a recompte en una graella, coordenades i expressions amb dues variables|Matemáticas: multiplicación como recuento en una rejilla, coordenadas y expresiones con dos variables",
      "Sostenibilitat i disseny: organitzar objectes reals ajustant les mides a l'ús|Sostenibilidad y diseño: organizar objetos reales ajustando las medidas al uso"],
    vocab: [["Bucles niats|Bucles anidados", "Un bucle dins d'un altre: el de dins es fa sencer a cada volta del de fora.|Un bucle dentro de otro: el de dentro se hace entero en cada vuelta del de fuera."],
      ["Graella|Rejilla", "Elements repartits en files i columnes, a distàncies iguals.|Elementos repartidos en filas y columnas, a distancias iguales."],
      ["Fila i columna|Fila y columna", "Les files van en la direcció y (comptador j) i les columnes en la direcció x (comptador i).|Las filas van en la dirección y (contador j) y las columnas en la dirección x (contador i)."],
      ["Marge|Margen", "La distància entre la vora de la placa i el primer element.|La distancia entre el borde de la placa y el primer elemento."],
      ["pas (al bucle)|paso (en el bucle)", "La quantitat que suma el comptador a cada volta: repeteix x de 0 a 60 pas 20.|La cantidad que suma el contador en cada vuelta: repite x de 0 a 60 paso 20."],
      ["Gradeta|Gradilla", "Suport amb forats per sostenir tubs d'assaig drets.|Soporte con agujeros para sostener tubos de ensayo de pie."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Graelles»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Rejillas»", "Projector i la presentació de la sessió|Proyector y la presentación de la sesión", "Paper quadriculat (la graella imprimible) i dos colors per parella|Papel cuadriculado (la rejilla imprimible) y dos colores por pareja"],
      imprimir: ["Fitxa: bucles niats|Ficha: bucles anidados", "Graella de paper per pintar els bucles|Rejilla de papel para pintar los bucles"],
      prep: ["Imprimir la graella i la fitxa (una per parella).|Imprimir la rejilla y la ficha (una por pareja).", "Si n'hi ha, portar una gradeta de veritat o una caixa de piles per ensenyar-la.|Si las hay, traer una gradilla de verdad o una caja de pilas para enseñarla.", "Provar l'organitzador de piles: els dos bucles van de 0 a (nx - 1) i de 0 a (ny - 1).|Probar el organizador de pilas: los dos bucles van de 0 a (nx - 1) y de 0 a (ny - 1)."] },
    plan: [
      { min: 5, t: "De la fila a la graella|De la fila a la rejilla", fase: 'inici', fa: "Recorda el bucle de la fila amb una predicció ràpida. Presenta la gradeta de 12 tubs: 3 files de 4. Com ho faríeu amb el que ja sabeu?|Recuerda el bucle de la fila con una predicción rápida. Presenta la gradilla de 12 tubos: 3 filas de 4. ¿Cómo lo haríais con lo que ya sabéis?",
        diu: ["Si copiem el bucle de la fila tres vegades, què hauríem de canviar a cada còpia?|Si copiamos el bucle de la fila tres veces, ¿qué tendríamos que cambiar en cada copia?"], slides: ['s1', 's2'], app: "Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.", org: "Tot el grup|Todo el grupo" },
      { min: 12, t: "Un bucle dins d'un altre|Un bucle dentro de otro", fase: 'teoria', fa: "Explica els bucles niats amb l'animació: el de fora tria la fila, el de dins fa totes les columnes. Llegiu el programa de la graella i després la gradeta amb resta. Acaba amb el pas i el càlcul de la mida de la placa amb marges.|Explica los bucles anidados con la animación: el de fuera elige la fila, el de dentro hace todas las columnas. Leed el programa de la rejilla y después la gradilla con resta. Acaba con el paso y el cálculo del tamaño de la placa con márgenes.",
        diu: ["En quin ordre surten les peces?|¿En qué orden salen las piezas?", "Per què els dos comptadors tenen noms diferents?|¿Por qué los dos contadores tienen nombres distintos?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: "Tot el grup|Todo el grupo" },
      { min: 10, t: "La graella de paper|La rejilla de papel", fase: 'desconnectat', fa: "Per parelles: una persona llegeix el bucle niat de la fitxa i l'altra pinta les caselles a la graella, numerant-les en l'ordre en què surten. Comproven que surten files × columnes. Canvien els papers amb el segon programa.|Por parejas: una persona lee el bucle anidado de la ficha y la otra pinta las casillas en la rejilla, numerándolas en el orden en que salen. Comprueban que salen filas × columnas. Cambian los papeles con el segundo programa.",
        diu: ["Quina casella has pintat la sisena? Per què?|¿Qué casilla has pintado la sexta? ¿Por qué?"], slides: ['s8'], app: "Encara no: graella i colors.|Todavía no: rejilla y colores.", org: "Per parelles|Por parejas" },
      { min: 22, t: "A l'ordinador: gradeta, teclat i organitzador|En el ordenador: gradilla, teclado y organizador", fase: 'ordinador', fa: "Fan la sessió a l'app: prediccions (una graella vertical!), dos errors per trobar i els reptes (de fila a graella, gradeta, teclat i organitzador paramètric). A la gradeta, demana que comprovin al 3D, amb la vista de dalt, que els forats no toquen la vora.|Hacen la sesión en la app: predicciones (¡una rejilla vertical!), dos errores para encontrar y los retos (de fila a rejilla, gradilla, teclado y organizador paramétrico). En la gradilla, pide que comprueben en el 3D, con la vista de arriba, que los agujeros no tocan el borde.",
        diu: ["Quina coordenada fa servir j? I i?|¿Qué coordenada usa j? ¿Y i?", "Amb nx = 8, la placa i els forats encara quadren?|Con nx = 8, ¿la placa y los agujeros todavía cuadran?"], slides: ['s9', 's10', 's11', 's12'], app: "Sessió «Graelles», fins al disseny lliure.|Sesión «Rejillas», hasta el diseño libre.", org: "Individual|Individual" },
      { min: 6, t: "El meu organitzador|Mi organizador", fase: 'crea', fa: "Disseny lliure: un organitzador amb graella de forats (porta-llapis, porta-espècies, caixa de botons…). Que mesurin un objecte real i hi ajustin els forats. Es desa a «Projectes».|Diseño libre: un organizador con rejilla de agujeros (portalápices, especiero, caja de botones…). Que midan un objeto real y le ajusten los agujeros. Se guarda en «Proyectos».",
        diu: ["Quin objecte hi guardaràs? Quant fa de diàmetre?|¿Qué objeto guardarás? ¿Cuánto mide de diámetro?"], slides: ['s13'], app: "Pas «Dissenya un organitzador amb graella».|Paso «Diseña un organizador con rejilla».", org: "Individual|Individual" },
      { min: 5, t: "Tancament|Cierre", fase: 'tancament', fa: "Repassa les idees clau i el tiquet de sortida.|Repasa las ideas clave y el ticket de salida.", diu: ["Quantes voltes fa un bucle de 0 a 3 dins d'un de 0 a 4?|¿Cuántas vueltas da un bucle de 0 a 3 dentro de uno de 0 a 4?"], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: "Tot el grup|Todo el grupo" }
    ],
    errors: [["Fa servir el mateix nom (i) als dos bucles.|Usa el mismo nombre (i) en los dos bucles.", "El de dins tapa el de fora i les files se superposen. Que canviï el de dins per j i el faci servir a la y.|El de dentro tapa al de fuera y las filas se superponen. Que cambie el de dentro por j y lo use en la y."],
      ["Els forats tallen la vora de la placa.|Los agujeros cortan el borde de la placa.", "Que calculi on acaba l'últim forat: marge + (n − 1) × pas + radi. Si passa de la mida de la placa, cal un bucle més curt o una placa més gran.|Que calcule dónde acaba el último agujero: margen + (n − 1) × paso + radio. Si pasa del tamaño de la placa, hace falta un bucle más corto o una placa más grande."],
      ["Posa els bucles fora de la resta i surten cilindres sòlids.|Pone los bucles fuera de la resta y salen cilindros sólidos.", "Tot el que s'ha de restar ha d'anar dins de les claus de la resta, després de la placa. Que miri els blocs: els bucles han de quedar a dins del bloc resta.|Todo lo que hay que restar tiene que ir dentro de las llaves de la resta, después de la placa. Que mire los bloques: los bucles tienen que quedar dentro del bloque resta."]],
    diff: { mes: "Fer la paret en piràmide ⭐ (el final del bucle de dins depèn del de fora) i, després, una piràmide de 3D de veritat amb tres bucles niats (x, y, z).|Hacer la pared en pirámide ⭐ (el final del bucle de dentro depende del de fuera) y, después, una pirámide 3D de verdad con tres bucles anidados (x, y, z).",
      menys: "Començar convertint la fila en graella amb blocs, i fer la taula de la fitxa (j, i, posició) abans de programar la gradeta.|Empezar convirtiendo la fila en rejilla con bloques, y hacer la tabla de la ficha (j, i, posición) antes de programar la gradilla." },
    aval: { ticket: ["Quantes peces fa un bucle de 0 a 3 dins d'un bucle de 0 a 4?|¿Cuántas piezas hace un bucle de 0 a 3 dentro de un bucle de 0 a 4?", "Per què cada bucle necessita el seu comptador?|¿Por qué cada bucle necesita su contador?"],
      rubric: [["Bucles niats|Bucles anidados", "Explica l'ordre en què es fan les peces i en calcula el nombre.|Explica el orden en que se hacen las piezas y calcula su número.", "Fa la graella, però no sap explicar l'ordre.|Hace la rejilla, pero no sabe explicar el orden."],
        ["Graella de forats|Rejilla de agujeros", "Posa els bucles dins de la resta i calcula marges i pas.|Pone los bucles dentro de la resta y calcula márgenes y paso.", "Fa els forats, però tallen la vora o no hi caben.|Hace los agujeros, pero cortan el borde o no caben."],
        ["Paràmetres|Parámetros", "L'organitzador funciona amb qualsevol nx i ny.|El organizador funciona con cualquier nx y ny.", "Funciona amb els valors de partida.|Funciona con los valores de partida."]] },
    casa: "Mesura un objecte de casa que es guardi en graella (ous, piles, llapis, retoladors…) i calcula la placa d'un organitzador de 3 × 4: diàmetre dels forats, pas i marges.|Mide un objeto de casa que se guarde en rejilla (huevos, pilas, lápices, rotuladores…) y calcula la placa de un organizador de 3 × 4: diámetro de los agujeros, paso y márgenes.",
    intro: "Els bucles niats són un dels primers «salts» d'abstracció de la programació: un bucle que es repeteix sencer dins d'un altre. La graella de paper ajuda molt a veure l'ordre fila a fila abans de passar al 3D.|Los bucles anidados son uno de los primeros «saltos» de abstracción de la programación: un bucle que se repite entero dentro de otro. La rejilla de papel ayuda mucho a ver el orden fila a fila antes de pasar al 3D.",
    claus: ["El bucle de dins es fa sencer a cada volta del de fora.|El bucle de dentro se hace entero en cada vuelta del de fuera.", "Peces = files × columnes; cada bucle té el seu comptador.|Piezas = filas × columnas; cada bucle tiene su contador.", "Dins de resta, una graella de cilindres fa molts forats iguals.|Dentro de resta, una rejilla de cilindros hace muchos agujeros iguales.", "La mida de la placa surt dels marges, el pas i el nombre d'elements.|El tamaño de la placa sale de los márgenes, el paso y el número de elementos."],
    prev: ["Haver fet la sessió «Repetir en fila».|Haber hecho la sesión «Repetir en fila».", "Conèixer resta (unitat 3).|Conocer resta (unidad 3).", "Saber multiplicar i fer servir variables en expressions.|Saber multiplicar y usar variables en expresiones."],
    faq: [["Puc posar tres bucles un dins de l'altre?|¿Puedo poner tres bucles uno dentro de otro?", "Sí: amb tres comptadors (i, j, k) es fan graelles en 3D, com una pila de cubs. Compte amb el nombre de peces: 5 × 5 × 5 ja són 125.|Sí: con tres contadores (i, j, k) se hacen rejillas en 3D, como una pila de cubos. Cuidado con el número de piezas: 5 × 5 × 5 ya son 125."],
      ["És millor fer servir pas o multiplicar?|¿Es mejor usar paso o multiplicar?", "Fan el mateix. Amb pas, el comptador ja és la posició; multiplicant, el comptador és el número de la còpia. Si necessites saber «quina còpia és», multiplica.|Hacen lo mismo. Con paso, el contador ya es la posición; multiplicando, el contador es el número de la copia. Si necesitas saber «qué copia es», multiplica."],
      ["Per què els forats de la gradeta no travessen?|¿Por qué los agujeros de la gradilla no atraviesan?", "Comencen a z = 3: el fons de 3 mm aguanta els tubs. En un organitzador de llapis passa el mateix; en una brida, en canvi, els forats han de travessar.|Empiezan en z = 3: el fondo de 3 mm aguanta los tubos. En un organizador de lápices pasa lo mismo; en una brida, en cambio, los agujeros tienen que atravesar."]],
    tec: [["Amb molts forats, el resultat tarda a sortir.|Con muchos agujeros, el resultado tarda en salir.", "La resta amb molts cilindres costa de calcular. Proveu amb pocs forats (nx = 2) i augmenteu al final.|La resta con muchos cilindros cuesta de calcular. Probad con pocos agujeros (nx = 2) y aumentad al final."],
      ["No es veuen els forats al 3D.|No se ven los agujeros en el 3D.", "Activeu el botó «Resultat», que fa la resta, i mireu des de dalt.|Activad el botón «Resultado», que hace la resta, y mirad desde arriba."],
      ["El bloc «repeteix» nou queda fora de l'altre.|El bloque «repite» nuevo queda fuera del otro.", "Per embolcallar un bucle amb un altre és més fàcil a la pestanya «Codi»: escriviu la línia del repeteix a sobre i la clau } a sota.|Para envolver un bucle con otro es más fácil en la pestaña «Código»: escribid la línea del repite encima y la llave } debajo."]],
    extra: ["Fer un tauler d'escacs amb dos colors fent dos bucles: un per a les caselles parelles i un per a les senars.|Hacer un tablero de ajedrez con dos colores haciendo dos bucles: uno para las casillas pares y otro para las impares.", "Fer un niu d'abelles: graella amb files desplaçades mig pas (pista: j * 0.5 a la x).|Hacer un panal de abejas: rejilla con filas desplazadas medio paso (pista: j * 0.5 en la x).", "Dissenyar una caixa d'ous paramètrica per a 6, 10 o 12 ous.|Diseñar una huevera paramétrica para 6, 10 o 12 huevos."],
    trans: ["Sessió següent: patrons circulars amb gira.|Sesión siguiente: patrones circulares con gira.", "Matemàtiques: la multiplicació com a àrea (files × columnes) i les coordenades cartesianes.|Matemáticas: la multiplicación como área (filas × columnas) y las coordenadas cartesianas."],
    slides: [
      { id: 's1', k: 'portada', t: 'Graelles|Rejillas', x: "Un bucle dins d'un altre|Un bucle dentro de otro", nota: "Presenta la gradeta de 12 tubs d'assaig.|Presenta la gradilla de 12 tubos de ensayo." },
      { id: 's2', k: 'pregunta', t: '12 tubs: 3 files de 4|12 tubos: 3 filas de 4', x: "Ja sabem fer una fila. Com en fem tres sense copiar el codi?|Ya sabemos hacer una fila. ¿Cómo hacemos tres sin copiar el código?", code: CK(`repeteix i de 0 a 3 {\n  mou(i * 20, 0, 0) cub(15)\n}`), nota: "Recull idees: «repetir la fila» és la clau.|Recoge ideas: «repetir la fila» es la clave." },
      { id: 's3', k: 'anim', t: "Bucles niats|Bucles anidados", anim: 'p5nest', nota: "Fes notar l'ordre: tota la fila j = 0, després la j = 1…|Haz notar el orden: toda la fila j = 0, después la j = 1…" },
      { id: 's4', k: 'media', t: 'i per a la x, j per a la y|i para la x, j para la y', media: { k: 'model', prog: GRID }, nota: "4 × 3 = 12 cubs. Pregunta què passaria si els dos comptadors es diguessin i.|4 × 3 = 12 cubos. Pregunta qué pasaría si los dos contadores se llamaran i." },
      { id: 's5', k: 'media', t: "La gradeta: una graella de forats|La gradilla: una rejilla de agujeros", media: { k: 'model', prog: GRAD }, nota: "Els bucles van dins de la resta. Els forats comencen a z = 3: fons de 3 mm.|Los bucles van dentro de la resta. Los agujeros empiezan en z = 3: fondo de 3 mm." },
      { id: 's6', k: 'media', t: 'El pas del bucle|El paso del bucle', media: { k: 'model', prog: PASDEMO }, nota: "x val 0, 20, 40 i 60. És el mateix que mou(i * 20, …) amb i de 0 a 3.|x vale 0, 20, 40 y 60. Es lo mismo que mueve(i * 20, …) con i de 0 a 3." },
      { id: 's7', k: 'concepte', t: 'Calcular la placa|Calcular la placa', x: "Amplada = marge + (columnes − 1) × pas + element + marge|Anchura = margen + (columnas − 1) × paso + elemento + margen", punts: ["Teclat: 6 + 2 × 22 + 18 + 6 = 74 mm.|Teclado: 6 + 2 × 22 + 18 + 6 = 74 mm.", "Gradeta: 8 + 3 × 20 + 14 + 8 = 90 mm.|Gradilla: 8 + 3 × 20 + 14 + 8 = 90 mm."], nota: "Que facin el càlcul de la gradeta a la llibreta.|Que hagan el cálculo de la gradilla en la libreta." },
      { id: 's8', k: 'activitat', t: 'La graella de paper|La rejilla de papel', timer: 8, punts: ["Una persona llegeix el bucle niat.|Una persona lee el bucle anidado.", "L'altra pinta i numera les caselles.|La otra pinta y numera las casillas.", "Comproveu: files × columnes.|Comprobad: filas × columnas."], nota: "Per parelles, amb la graella imprimible i dos colors.|Por parejas, con la rejilla imprimible y dos colores." },
      { id: 's9', k: 'pregunta', t: 'Prediu: on van els cubs?|Predice: ¿dónde van los cubos?', code: CK(`repeteix i de 0 a 2 {\n  repeteix j de 0 a 2 {\n    mou(i * 20, 0, j * 20) cub(15)\n  }\n}`), nota: "j és a la z: una paret vertical de 3 × 3.|j está en la z: una pared vertical de 3 × 3." },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ["De fila a graella.|De fila a rejilla.", "La gradeta i el teclat.|La gradilla y el teclado.", "L'organitzador de piles (nx × ny).|El organizador de pilas (nx × ny)."], nota: "Recorda la vista de dalt per comprovar els marges.|Recuerda la vista de arriba para comprobar los márgenes." },
      { id: 's11', k: 'media', t: 'El teclat numèric|El teclado numérico', media: { k: 'model', prog: KEYPAD }, nota: "Tecles a z = 6, sobre la base. Posició (6 + i * 22, 6 + j * 22).|Teclas en z = 6, sobre la base. Posición (6 + i * 22, 6 + j * 22)." },
      { id: 's12', k: 'media', t: "L'organitzador paramètric|El organizador paramétrico", media: { k: 'model', prog: PILES }, nota: "La placa fa nx × 19 + 6. Els bucles: de 0 a (nx - 1) i de 0 a (ny - 1).|La placa mide nx × 19 + 6. Los bucles: de 0 a (nx - 1) y de 0 a (ny - 1)." },
      { id: 's13', k: 'repte', t: 'El meu organitzador|Mi organizador', punts: ["Dos bucles niats.|Dos bucles anidados.", "Forats amb resta, amb fons.|Agujeros con resta, con fondo.", "Una sola peça a la placa.|Una sola pieza en la placa."], nota: "Que mesurin l'objecte real abans de programar.|Que midan el objeto real antes de programar." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Un bucle dins d'un altre fa una graella.|Un bucle dentro de otro hace una rejilla.", "Peces = files × columnes.|Piezas = filas × columnas.", "Graella + resta = molts forats iguals.|Rejilla + resta = muchos agujeros iguales."], nota: "Llegiu-ho junts.|Leedlo juntos." },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Quantes peces fa un bucle de 0 a 3 dins d'un de 0 a 4?|¿Cuántas piezas hace un bucle de 0 a 3 dentro de uno de 0 a 4?", "Per què cada bucle té el seu comptador?|¿Por qué cada bucle tiene su contador?"], nota: "Oral o en un paper.|Oral o en un papel." }
    ],
    print: [{ id: 'p1', t: 'Fitxa: bucles niats|Ficha: bucles anidados', k: 'fitxa', intro: "Llegeix cada programa, respon i, si cal, dibuixa'l a la graella.|Lee cada programa, responde y, si hace falta, dibújalo en la rejilla.",
      items: [{ q: "<code>repeteix fila de 0 a 2 { repeteix col de 0 a 4 { pinta (col × 2, fila × 2) } }</code><br>Quantes caselles pintes? Quina és la sisena?|<code>repite fila de 0 a 2 { repite col de 0 a 4 { pinta (col × 2, fila × 2) } }</code><br>¿Cuántas casillas pintas? ¿Cuál es la sexta?", sol: "3 × 5 = 15 caselles. La sisena és la primera de la segona fila: (0, 2).|3 × 5 = 15 casillas. La sexta es la primera de la segunda fila: (0, 2)." },
        { q: "<code>repeteix j de 0 a 3 { repeteix i de 0 a 1 { mou(i * 30, j * 30, 0) cub(20) } }</code>: quantes files i columnes té? Quant fa d'ample i de fons?|<code>repite j de 0 a 3 { repite i de 0 a 1 { mueve(i * 30, j * 30, 0) cubo(20) } }</code>: ¿cuántas filas y columnas tiene? ¿Cuánto mide de ancho y de fondo?", sol: "2 columnes i 4 files (8 cubs). Ample: 30 + 20 = 50 mm; fons: 3 × 30 + 20 = 110 mm.|2 columnas y 4 filas (8 cubos). Ancho: 30 + 20 = 50 mm; fondo: 3 × 30 + 20 = 110 mm." },
        { q: "Una gradeta de 2 × 5 forats de 16 mm, pas 22 i marge 6. Quines mides ha de tenir la placa?|Una gradilla de 2 × 5 agujeros de 16 mm, paso 22 y margen 6. ¿Qué medidas tiene que tener la placa?", sol: "Amplada: 6 + 4 × 22 + 16 + 6 = 116 mm. Fondària: 6 + 1 × 22 + 16 + 6 = 50 mm.|Anchura: 6 + 4 × 22 + 16 + 6 = 116 mm. Fondo: 6 + 1 × 22 + 16 + 6 = 50 mm." }] },
      { id: 'p2', t: 'Graella de paper|Rejilla de papel', k: 'graella', w: 10, h: 8, intro: "Pinta les caselles en l'ordre que diu el bucle i escriu-hi el número d'ordre. Cada casella és una unitat.|Pinta las casillas en el orden que dice el bucle y escribe el número de orden. Cada casilla es una unidad.",
        legend: [['■', "Casella pintada|Casilla pintada"], ['1, 2, 3…', "Ordre en què la pintes|Orden en que la pintas"], ['→ x', "Columnes (comptador col)|Columnas (contador col)"], ['↑ y', "Files (comptador fila)|Filas (contador fila)"]],
        items: [{ q: "Programa 2: <code>repeteix fila de 0 a 1 { repeteix col de 0 a 3 { pinta (col × 3, fila × 4) } }</code>. Quantes caselles has pintat?|Programa 2: <code>repite fila de 0 a 1 { repite col de 0 a 3 { pinta (col × 3, fila × 4) } }</code>. ¿Cuántas casillas has pintado?" }] }]
  },
  /* ---------- Sessió 3 · Patrons circulars ---------- */
  'p5-3': {
    obj: ["L'alumne/a reparteix n còpies en un cercle amb gira(0, 0, i * 360 / n) mou(r, 0, 0).|El alumno/a reparte n copias en un círculo con gira(0, 0, i * 360 / n) mueve(r, 0, 0).",
      "L'alumne/a calcula l'angle entre còpies (360 / n) i justifica per què el bucle va de 0 a n − 1.|El alumno/a calcula el ángulo entre copias (360 / n) y justifica por qué el bucle va de 0 a n − 1.",
      "L'alumne/a explica l'efecte de l'ordre de les transformacions (gira i mou) en un patró circular.|El alumno/a explica el efecto del orden de las transformaciones (gira y mueve) en un patrón circular.",
      "L'alumne/a reconeix la simetria de rotació en objectes naturals i tècnics i la fa servir en un disseny propi.|El alumno/a reconoce la simetría de rotación en objetos naturales y técnicos y la usa en un diseño propio."],
    comp: ["Tecnologia i digitalització: CAD 3D de peces amb patrons circulars (rodes, brides, rellotges)|Tecnología y digitalización: CAD 3D de piezas con patrones circulares (ruedas, bridas, relojes)",
      "Matemàtiques: angles, divisors de 360, circumferència i simetria de rotació|Matemáticas: ángulos, divisores de 360, circunferencia y simetría de rotación",
      "Pensament computacional: composició de transformacions dins d'un bucle i depuració|Pensamiento computacional: composición de transformaciones dentro de un bucle y depuración",
      "Consciència i expressió cultural: patrons circulars a l'art, la natura i l'artesania (mandales, rosasses)|Conciencia y expresión cultural: patrones circulares en el arte, la naturaleza y la artesanía (mandalas, rosetones)"],
    vocab: [["Patró circular|Patrón circular", "Còpies d'una peça repartides al voltant d'un centre, a la mateixa distància.|Copias de una pieza repartidas alrededor de un centro, a la misma distancia."],
      ["Radi|Radio", "La distància del centre del cercle a cada còpia: el número del mou.|La distancia del centro del círculo a cada copia: el número del mueve."],
      ["Angle|Ángulo", "Quant gira cada còpia, en graus. Una volta sencera són 360°.|Cuánto gira cada copia, en grados. Una vuelta entera son 360°."],
      ["Simetria de rotació|Simetría de rotación", "Una figura la té si queda igual després de girar-la un angle (menys de 360°).|Una figura la tiene si queda igual después de girarla un ángulo (menos de 360°)."],
      ["Composició de transformacions|Composición de transformaciones", "Aplicar diverses transformacions seguides: l'ordre canvia el resultat.|Aplicar varias transformaciones seguidas: el orden cambia el resultado."],
      ["Brida|Brida", "Peça en forma de disc amb forats en cercle per unir tubs o eixos amb cargols.|Pieza en forma de disco con agujeros en círculo para unir tubos o ejes con tornillos."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Patrons circulars»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Patrones circulares»", "Projector i la presentació de la sessió|Proyector y la presentación de la sesión", "Compàs, transportador i regle per alumne/a|Compás, transportador y regla por alumno/a"],
      imprimir: ["Fitxa: cercles i angles|Ficha: círculos y ángulos"],
      prep: ["Comprovar que hi ha prou compassos i transportadors.|Comprobar que hay suficientes compases y transportadores.", "Tenir a punt una foto o un objecte amb simetria de rotació (una flor, una roda de bicicleta, una rosassa).|Tener preparada una foto o un objeto con simetría de rotación (una flor, una rueda de bicicleta, un rosetón).", "Provar la flor paramètrica amb n = 3 i n = 8.|Probar la flor paramétrica con n = 3 y n = 8."] },
    plan: [
      { min: 5, t: "Rellotges i flors|Relojes y flores", fase: 'inici', fa: "Recorda com gira gira (al voltant de l'origen) amb la predicció del cub. Presenta els dos encàrrecs: el rellotge de 12 marques i les flors de l'hort. Ensenya un objecte amb simetria de rotació.|Recuerda cómo gira gira (alrededor del origen) con la predicción del cubo. Presenta los dos encargos: el reloj de 12 marcas y las flores del huerto. Enseña un objeto con simetría de rotación.",
        diu: ["Si les 12 marques no van en fila, com les col·locaríeu?|Si las 12 marcas no van en fila, ¿cómo las colocaríais?"], slides: ['s1', 's2'], app: "Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.", org: "Tot el grup|Todo el grupo" },
      { min: 12, t: "Allunyar i girar|Alejar y girar", fase: 'teoria', fa: "Amb l'animació: mou allunya la peça (radi) i gira la fa voltar al voltant de l'origen. Calculeu 360 / n per a diversos n. Compara l'ordre correcte i l'equivocat del rellotge. Acaba amb la simetria de rotació de la roda.|Con la animación: mueve aleja la pieza (radio) y gira la hace dar vueltas alrededor del origen. Calculad 360 / n para varios n. Compara el orden correcto y el equivocado del reloj. Acaba con la simetría de rotación de la rueda.",
        diu: ["Si fem el bucle de 0 a n, on queda l'última còpia?|Si hacemos el bucle de 0 a n, ¿dónde queda la última copia?", "Què passa si escrivim mou abans de gira?|¿Qué pasa si escribimos mueve antes de gira?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: "Tot el grup|Todo el grupo" },
      { min: 10, t: "Cercles amb transportador|Círculos con transportador", fase: 'desconnectat', fa: "Cada alumne/a dibuixa dos cercles de 5 cm de radi i hi marca 8 i 5 punts amb el transportador (45° i 72°). Després completen la taula de la fitxa: per a quins n l'angle és un nombre enter.|Cada alumno/a dibuja dos círculos de 5 cm de radio y marca 8 y 5 puntos con el transportador (45° y 72°). Después completan la tabla de la ficha: para qué n el ángulo es un número entero.",
        diu: ["Per què el 12 és un bon nombre per a un rellotge?|¿Por qué el 12 es un buen número para un reloj?"], slides: ['s8'], app: "Encara no: compàs, transportador i fitxa.|Todavía no: compás, transportador y ficha.", org: "Individual|Individual" },
      { min: 22, t: "A l'ordinador: rellotge, flor i roda|En el ordenador: reloj, flor y rueda", fase: 'ordinador', fa: "Fan la sessió a l'app: prediccions, els dos errors del rellotge (angle i ordre) i els reptes (cercle de cilindres, rellotge, flor paramètrica i roda amb radis). A la flor, que provin n = 3 i n = 8 abans de donar-la per acabada.|Hacen la sesión en la app: predicciones, los dos errores del reloj (ángulo y orden) y los retos (círculo de cilindros, reloj, flor paramétrica y rueda con radios). En la flor, que prueben n = 3 y n = 8 antes de darla por terminada.",
        diu: ["Quin angle toca amb 12 marques? I amb n pètals?|¿Qué ángulo toca con 12 marcas? ¿Y con n pétalos?", "La marca està centrada sobre el radi? Per què hi ha un −2?|¿La marca está centrada sobre el radio? ¿Por qué hay un −2?"], slides: ['s9', 's10', 's11', 's12'], app: "Sessió «Patrons circulars», fins al disseny lliure.|Sesión «Patrones circulares», hasta el diseño libre.", org: "Individual|Individual" },
      { min: 6, t: "El meu patró circular|Mi patrón circular", fase: 'crea', fa: "Disseny lliure amb un patró circular: flor, mandala, corona, posavasos, roda… Que facin servir 360 / n i comprovin que és una sola peça. Es desa a «Projectes».|Diseño libre con un patrón circular: flor, mandala, corona, posavasos, rueda… Que usen 360 / n y comprueben que es una sola pieza. Se guarda en «Proyectos».",
        diu: ["Quina simetria de rotació té el teu disseny?|¿Qué simetría de rotación tiene tu diseño?"], slides: ['s13'], app: "Pas «Dissenya un patró circular».|Paso «Diseña un patrón circular».", org: "Individual|Individual" },
      { min: 5, t: "Tancament|Cierre", fase: 'tancament', fa: "Repassa les idees clau i el tiquet de sortida.|Repasa las ideas clave y el ticket de salida.", diu: ["Quants graus gira cada còpia si n'hi ha 8? Per què el bucle va fins a n − 1?|¿Cuántos grados gira cada copia si hay 8? ¿Por qué el bucle va hasta n − 1?"], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: "Tot el grup|Todo el grupo" }
    ],
    errors: [["Totes les còpies surten amuntegades en un punt.|Todas las copias salen amontonadas en un punto.", "Ha escrit mou abans de gira. Que llegeixi la línia des de la forma cap a l'esquerra: primer s'aplica el que és més a prop de la forma.|Ha escrito mueve antes de gira. Que lea la línea desde la forma hacia la izquierda: primero se aplica lo que está más cerca de la forma."],
      ["Hi ha una còpia de més a sobre de la primera, o el cercle no es tanca.|Hay una copia de más encima de la primera, o el círculo no se cierra.", "Que revisi els extrems del bucle (de 0 a n − 1) i que l'angle multiplicat per les còpies doni 360.|Que revise los extremos del bucle (de 0 a n − 1) y que el ángulo multiplicado por las copias dé 360."],
      ["Les marques del rellotge no queden centrades sobre el radi.|Las marcas del reloj no quedan centradas sobre el radio.", "El cub té una cantonada a l'origen: cal desplaçar-lo mitja amplada en y (−2 si fa 4 d'ample) abans de girar-lo.|El cubo tiene una esquina en el origen: hay que desplazarlo media anchura en y (−2 si mide 4 de ancho) antes de girarlo."]],
    diff: { mes: "Fer la brida ⭐ amb forats per a cargols i, després, una rosassa amb dos patrons circulars de radis i angles diferents, desplaçats mig angle.|Hacer la brida ⭐ con agujeros para tornillos y, después, un rosetón con dos patrones circulares de radios y ángulos distintos, desplazados medio ángulo.",
      menys: "Treballar amb blocs i fer primer la taula de la fitxa (i, angle) per a 6 còpies. Al rellotge, donar-li el mou(30, -2, 4) escrit.|Trabajar con bloques y hacer primero la tabla de la ficha (i, ángulo) para 6 copias. En el reloj, darle el mueve(30, -2, 4) escrito." },
    aval: { ticket: ["Quants graus gira cada còpia si en volem 8 en cercle?|¿Cuántos grados gira cada copia si queremos 8 en círculo?", "Per què el bucle va de 0 a n − 1?|¿Por qué el bucle va de 0 a n − 1?"],
      rubric: [["Patró circular|Patrón circular", "Escriu gira i mou en l'ordre correcte i explica per què.|Escribe gira y mueve en el orden correcto y explica por qué.", "Ho aconsegueix canviant l'ordre a prova i error.|Lo consigue cambiando el orden a prueba y error."],
        ["Angles|Ángulos", "Calcula 360 / n i els extrems del bucle sense provar.|Calcula 360 / n y los extremos del bucle sin probar.", "Necessita provar diversos angles.|Necesita probar varios ángulos."],
        ["Disseny paramètric|Diseño paramétrico", "La flor funciona amb qualsevol n.|La flor funciona con cualquier n.", "Funciona amb un sol n.|Funciona con un solo n."]] },
    casa: "Busca a casa o al carrer tres objectes amb simetria de rotació (una tapa, una roda, una flor, un ventilador…). Per a cada un, compta n i calcula l'angle 360 / n.|Busca en casa o en la calle tres objetos con simetría de rotación (una tapa, una rueda, una flor, un ventilador…). Para cada uno, cuenta n y calcula el ángulo 360 / n.",
    intro: "Aquesta sessió ajunta tres coses que ja coneixen (bucles, gira al voltant de l'origen i l'ordre de les transformacions) per fer patrons circulars. L'activitat amb transportador fa visible l'angle 360 / n abans de programar-lo.|Esta sesión junta tres cosas que ya conocen (bucles, gira alrededor del origen y el orden de las transformaciones) para hacer patrones circulares. La actividad con transportador hace visible el ángulo 360 / n antes de programarlo.",
    claus: ["Patró circular: gira(0, 0, i * 360 / n) mou(r, 0, 0) forma.|Patrón circular: gira(0, 0, i * 360 / n) mueve(r, 0, 0) forma.", "L'angle entre còpies és 360 / n; el bucle va de 0 a n − 1.|El ángulo entre copias es 360 / n; el bucle va de 0 a n − 1.", "La transformació més a prop de la forma s'aplica primer.|La transformación más cerca de la forma se aplica primero.", "Per centrar una peça sobre el radi, es desplaça mitja amplada.|Para centrar una pieza sobre el radio, se desplaza media anchura."],
    prev: ["Haver fet «Repetir en fila» i «Graelles».|Haber hecho «Repetir en fila» y «Rejillas».", "Saber que gira fa girar al voltant de l'origen i que l'ordre importa (unitat 2).|Saber que gira hace girar alrededor del origen y que el orden importa (unidad 2).", "Saber fer servir el transportador.|Saber usar el transportador."],
    faq: [["I si vull que les còpies no girin, que mirin totes cap al mateix costat?|¿Y si quiero que las copias no giren, que miren todas hacia el mismo lado?", "Llavors no es fa servir gira: es calcula la posició amb cos i sin: mou(r * cos(i * 360 / n), r * sin(i * 360 / n), 0). Per a peces rodones (cilindres) no es nota la diferència.|Entonces no se usa gira: se calcula la posición con cos y sin: mueve(r * cos(i * 360 / n), r * sin(i * 360 / n), 0). Para piezas redondas (cilindros) no se nota la diferencia."],
      ["Puc fer un patró en espiral?|¿Puedo hacer un patrón en espiral?", "Sí: si a cada volta, a més de girar, la peça puja (mou(0, 0, i * 5)) o s'allunya una mica més, surt una espiral o una escala de cargol.|Sí: si en cada vuelta, además de girar, la pieza sube (mueve(0, 0, i * 5)) o se aleja un poco más, sale una espiral o una escalera de caracol."],
      ["Per què 360 graus?|¿Por qué 360 grados?", "És un conveni molt antic, possiblement dels babilonis. 360 es pot dividir exactament entre molts nombres (2, 3, 4, 5, 6, 8, 9, 10, 12…), i això és molt pràctic.|Es una convención muy antigua, posiblemente de los babilonios. 360 se puede dividir exactamente entre muchos números (2, 3, 4, 5, 6, 8, 9, 10, 12…), y eso es muy práctico."]],
    tec: [["No es veu si les marques miren al centre.|No se ve si las marcas miran al centro.", "Feu servir la vista de dalt (planta) del 3D.|Usad la vista de arriba (planta) del 3D."],
      ["Surt «escala amb un 0 aplana la forma».|Sale «escala con un 0 aplana la forma».", "Els tres números d'escala han de ser diferents de 0: per no canviar una mida, s'hi posa 1.|Los tres números de escala tienen que ser distintos de 0: para no cambiar una medida, se pone 1."],
      ["La roda sembla tenir els radis desencaixats.|La rueda parece tener los radios desencajados.", "Activeu «Resultat» per veure el sòlid final i comproveu que els radis entren 2 mm dins de la llanta.|Activad «Resultado» para ver el sólido final y comprobad que los radios entran 2 mm dentro de la llanta."]],
    extra: ["Fer una escala de cargol: cada esglaó gira 30° i puja 6 mm.|Hacer una escalera de caracol: cada peldaño gira 30° y sube 6 mm.", "Fer una rosassa amb dos o tres anells de peces amb angles diferents.|Hacer un rosetón con dos o tres anillos de piezas con ángulos distintos.", "Investigar quins polígons regulars surten unint els punts del cercle (360 / n és l'angle central).|Investigar qué polígonos regulares salen uniendo los puntos del círculo (360 / n es el ángulo central)."],
    trans: ["Sessió següent: projecte de l'engranatge paramètric.|Sesión siguiente: proyecto del engranaje paramétrico.", "Matemàtiques i Educació visual i plàstica: angles centrals, polígons regulars i simetria de rotació.|Matemáticas y Educación visual y plástica: ángulos centrales, polígonos regulares y simetría de rotación."],
    slides: [
      { id: 's1', k: 'portada', t: 'Patrons circulars|Patrones circulares', x: 'Rellotges, flors i rodes amb un bucle|Relojes, flores y ruedas con un bucle', nota: "Presenta el rellotge de la biblioteca i les flors de l'hort.|Presenta el reloj de la biblioteca y las flores del huerto." },
      { id: 's2', k: 'repas', t: 'On queda el cub?|¿Dónde queda el cubo?', code: CK(`gira(0, 0, 90) mou(30, 0, 0) cub(10)`), nota: "Primer es mou a +x i després gira 90° al voltant de l'origen: acaba a +y.|Primero se mueve a +x y después gira 90° alrededor del origen: acaba en +y." },
      { id: 's3', k: 'anim', t: 'Allunyar i girar|Alejar y girar', anim: 'p5orbit', nota: "mou fa el radi; gira reparteix les còpies: 360° / 8 = 45°.|mueve hace el radio; gira reparte las copias: 360° / 8 = 45°." },
      { id: 's4', k: 'media', t: "L'angle: 360 / n|El ángulo: 360 / n", media: { k: 'model', prog: ORB6 }, nota: "Amb n = 6, 60°. Pregunta què passaria amb el bucle de 0 a n.|Con n = 6, 60°. Pregunta qué pasaría con el bucle de 0 a n." },
      { id: 's5', k: 'media', t: 'El rellotge: primer gira, després mou|El reloj: primero gira, después mueve', media: { k: 'model', prog: CLOCK }, nota: "El −2 de la y centra la marca (fa 4 mm d'ample) sobre el radi.|El −2 de la y centra la marca (mide 4 mm de ancho) sobre el radio." },
      { id: 's6', k: 'media', t: "I si ho escrivim al revés?|¿Y si lo escribimos al revés?", media: { k: 'model', prog: CLOCKBAD }, nota: "Totes les marques giren a l'origen i després es mouen al mateix punt.|Todas las marcas giran en el origen y después se mueven al mismo punto." },
      { id: 's7', k: 'media', t: 'Simetria de rotació|Simetría de rotación', media: { k: 'model', prog: WHEEL }, nota: "8 radis: queda igual si la girem 45°. Ordre 8.|8 radios: queda igual si la giramos 45°. Orden 8." },
      { id: 's8', k: 'activitat', t: 'Cercles amb transportador|Círculos con transportador', timer: 8, punts: ["Cercle de 5 cm i 8 punts cada 45°.|Círculo de 5 cm y 8 puntos cada 45°.", "Un altre cercle amb 5 punts (72°).|Otro círculo con 5 puntos (72°).", "Taula: per a quins n l'angle és enter?|Tabla: ¿para qué n el ángulo es entero?"], nota: "Individual, amb compàs i transportador.|Individual, con compás y transportador." },
      { id: 's9', k: 'pregunta', t: 'Prediu: quants braços?|Predice: ¿cuántos brazos?', code: CK(`repeteix i de 0 a 4 {\n  gira(0, 0, i * 72) mou(4, -3, 0) cub(20, 6, 4)\n}`), nota: "5 braços: 5 × 72° = 360°.|5 brazos: 5 × 72° = 360°." },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ["Troba els errors del rellotge.|Encuentra los errores del reloj.", "Cercle de cilindres i rellotge.|Círculo de cilindros y reloj.", "Flor paramètrica i roda amb radis.|Flor paramétrica y rueda con radios."], nota: "La vista de dalt ajuda molt.|La vista de arriba ayuda mucho." },
      { id: 's11', k: 'media', t: 'La flor paramètrica|La flor paramétrica', media: { k: 'model', prog: FLOWER }, nota: "escala(1.6, 1, 1) estira el cilindre en x abans de girar-lo: pètals.|escala(1.6, 1, 1) estira el cilindro en x antes de girarlo: pétalos." },
      { id: 's12', k: 'concepte', t: 'La roda amb radis|La rueda con radios', x: "Cada radi surt del centre: mou(0, -2, 0) el centra sobre l'eix x.|Cada radio sale del centro: mueve(0, -2, 0) lo centra sobre el eje x.", code: CK(`repeteix i de 0 a 7 {\n  gira(0, 0, i * 45) mou(0, -2, 0) cub(32, 4, 6)\n}`), nota: "Els radis fan 32 i la llanta comença a 30: s'hi enganxen 2 mm.|Los radios miden 32 y la llanta empieza en 30: se enganchan 2 mm." },
      { id: 's13', k: 'repte', t: 'El meu patró circular|Mi patrón circular', punts: ["Un bucle amb gira.|Un bucle con gira.", "Angle 360 / n.|Ángulo 360 / n.", "Una sola peça a la placa.|Una sola pieza en la placa."], nota: "Idees: mandala, posavasos, corona, flor, roda.|Ideas: mandala, posavasos, corona, flor, rueda." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["gira(0, 0, i * 360 / n) mou(r, 0, 0) fa un cercle.|gira(0, 0, i * 360 / n) mueve(r, 0, 0) hace un círculo.", "El bucle va de 0 a n − 1.|El bucle va de 0 a n − 1.", "L'ordre de les transformacions importa.|El orden de las transformaciones importa."], nota: "Llegiu-ho junts.|Leedlo juntos." },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Quants graus per a 8 còpies?|¿Cuántos grados para 8 copias?", "Per què de 0 a n − 1?|¿Por qué de 0 a n − 1?"], nota: "Oral o en un paper.|Oral o en un papel." }
    ],
    print: [{ id: 'p1', t: 'Fitxa: cercles i angles|Ficha: círculos y ángulos', k: 'fitxa', intro: "Fes servir el compàs i el transportador. Els angles es mesuren des del radi de 0°, cap a l'esquerra (com gira).|Usa el compás y el transportador. Los ángulos se miden desde el radio de 0°, hacia la izquierda (como gira).",
      items: [{ q: "Dibuixa un cercle de 5 cm de radi i marca-hi 8 punts repartits. Quin angle hi ha entre dos punts seguits?|Dibuja un círculo de 5 cm de radio y marca 8 puntos repartidos. ¿Qué ángulo hay entre dos puntos seguidos?", big: true, sol: "360 / 8 = 45°: 0°, 45°, 90°, 135°, 180°, 225°, 270° i 315°.|360 / 8 = 45°: 0°, 45°, 90°, 135°, 180°, 225°, 270° y 315°." },
        { q: "Completa: n = 3, 4, 5, 6, 7, 8, 9, 10, 12 → angle 360 / n. Per a quins n l'angle és un nombre enter?|Completa: n = 3, 4, 5, 6, 7, 8, 9, 10, 12 → ángulo 360 / n. ¿Para qué n el ángulo es un número entero?", sol: "120, 90, 72, 60, 51,4…, 45, 40, 36, 30. Tots són enters menys n = 7 (7 no és divisor de 360).|120, 90, 72, 60, 51,4…, 45, 40, 36, 30. Todos son enteros menos n = 7 (7 no es divisor de 360)." },
        { q: "<code>repeteix i de 0 a 11 { gira(0, 0, i * 30) mou(30, -2, 4) cub(8, 4, 3) }</code>: quantes marques fa? Quin angle gira la marca número 4 (i = 4)?|<code>repite i de 0 a 11 { gira(0, 0, i * 30) mueve(30, -2, 4) cubo(8, 4, 3) }</code>: ¿cuántas marcas hace? ¿Qué ángulo gira la marca número 4 (i = 4)?", sol: "12 marques. La de i = 4 gira 120° (és on hi hauria les 4 si el 0° fos les 3).|12 marcas. La de i = 4 gira 120° (es donde estarían las 4 si el 0° fueran las 3)." },
        { q: "Una companya escriu <code>mou(30, -2, 4) gira(0, 0, i * 30) cub(8, 4, 3)</code>. Què li passa? Com ho arreglaries?|Una compañera escribe <code>mueve(30, -2, 4) gira(0, 0, i * 30) cubo(8, 4, 3)</code>. ¿Qué le pasa? ¿Cómo lo arreglarías?", sol: "Cada marca gira a l'origen i després es mou al mateix punt: no fan cercle. Cal escriure primer gira i després mou.|Cada marca gira en el origen y después se mueve al mismo punto: no hacen círculo. Hay que escribir primero gira y después mueve." }] }]
  },
  /* ---------- Sessió 4 · Projecte: l'engranatge ---------- */
  'p5-4': {
    obj: ["L'alumne/a modela un engranatge com un patró circular de dents sobre un disc, amb el forat de l'eix fet amb resta.|El alumno/a modela un engranaje como un patrón circular de dientes sobre un disco, con el agujero del eje hecho con resta.",
      "L'alumne/a fa servir variables d'enginyeria (z, m, d = m · z) perquè el disseny sigui paramètric i ho comprova amb diversos valors.|El alumno/a usa variables de ingeniería (z, m, d = m · z) para que el diseño sea paramétrico y lo comprueba con varios valores.",
      "L'alumne/a calcula la relació de transmissió i la distància entre centres de dues rodes que encaixen.|El alumno/a calcula la relación de transmisión y la distancia entre centros de dos ruedas que encajan.",
      "L'alumne/a aplica criteris de fabricació (peça única, forat que travessa, forats d'alleugeriment) i documenta el disseny.|El alumno/a aplica criterios de fabricación (pieza única, agujero que atraviesa, agujeros de aligeramiento) y documenta el diseño."],
    comp: ["Tecnologia i digitalització: mecanismes de transmissió (engranatges) i el procés de disseny i fabricació digital|Tecnología y digitalización: mecanismos de transmisión (engranajes) y el proceso de diseño y fabricación digital",
      "Matemàtiques: proporcionalitat (relació de transmissió), expressions amb diverses variables i angles|Matemáticas: proporcionalidad (relación de transmisión), expresiones con varias variables y ángulos",
      "Pensament computacional: generalització (un programa per a tota una família de peces) i proves amb diversos valors|Pensamiento computacional: generalización (un programa para toda una familia de piezas) y pruebas con varios valores",
      "Sostenibilitat: estalviar material i temps d'impressió sense perdre funcionalitat|Sostenibilidad: ahorrar material y tiempo de impresión sin perder funcionalidad"],
    vocab: [["Engranatge|Engranaje", "Roda dentada que transmet el moviment a una altra quan les dents encaixen.|Rueda dentada que transmite el movimiento a otra cuando los dientes encajan."],
      ["Pinyó i roda|Piñón y rueda", "En una parella d'engranatges, el pinyó és el petit i la roda, el gran.|En una pareja de engranajes, el piñón es el pequeño y la rueda, el grande."],
      ["Mòdul (m)|Módulo (m)", "La mida de les dents. Dues rodes només encaixen si tenen el mateix mòdul.|El tamaño de los dientes. Dos ruedas solo encajan si tienen el mismo módulo."],
      ["Diàmetre primitiu (d = m · z)|Diámetro primitivo (d = m · z)", "El cercle «de contacte» de la roda; els de dues rodes que encaixen es toquen.|El círculo «de contacto» de la rueda; los de dos ruedas que encajan se tocan."],
      ["Relació de transmissió|Relación de transmisión", "Quantes voltes fa el pinyó per cada volta de la roda: z de la roda / z del pinyó.|Cuántas vueltas da el piñón por cada vuelta de la rueda: z de la rueda / z del piñón."],
      ["Forat d'alleugeriment|Agujero de aligeramiento", "Forat que treu material d'una peça sense afeblir-la, per estalviar plàstic i temps.|Agujero que quita material de una pieza sin debilitarla, para ahorrar plástico y tiempo."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Projecte: l'engranatge»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Proyecto: el engranaje»", "Projector i la presentació de la sessió|Proyector y la presentación de la sesión", "Compàs, regle i calculadora per parella; si n'hi ha, engranatges de veritat (d'una joguina, un rellotge o un kit de tecnologia)|Compás, regla y calculadora por pareja; si los hay, engranajes de verdad (de un juguete, un reloj o un kit de tecnología)"],
      imprimir: ["Fitxa d'especificacions de l'engranatge|Ficha de especificaciones del engranaje"],
      prep: ["Si teniu impressora 3D, imprimir abans un pinyó de 8 i una roda de 16 (mòdul 3) per ensenyar com encaixen.|Si tenéis impresora 3D, imprimir antes un piñón de 8 y una rueda de 16 (módulo 3) para enseñar cómo encajan.", "Provar el pas 3 (paramètric) amb z = 8 i z = 20: el bucle va de 0 a (z - 1).|Probar el paso 3 (paramétrico) con z = 8 y z = 20: el bucle va de 0 a (z - 1).", "Preparar la fitxa tècnica que faran al final (o fer-la a la llibreta).|Preparar la ficha técnica que harán al final (o hacerla en la libreta)."] },
    plan: [
      { min: 5, t: "L'encàrrec de l'autòmat|El encargo del autómata", fase: 'inici', fa: "Presenta l'autòmat de 2n d'ESO i ensenya engranatges de veritat. Feu girar dues rodes i compteu voltes. Recorda el patró circular amb la predicció.|Presenta el autómata de 2.º de ESO y enseña engranajes de verdad. Haced girar dos ruedas y contad vueltas. Recuerda el patrón circular con la predicción.",
        diu: ["Si la gran té el doble de dents, quantes voltes fa la petita per cada volta de la gran?|Si la grande tiene el doble de dientes, ¿cuántas vueltas da la pequeña por cada vuelta de la grande?"], slides: ['s1', 's2'], app: "Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.", org: "Tot el grup|Todo el grupo" },
      { min: 8, t: "Com és un engranatge|Cómo es un engranaje", fase: 'teoria', fa: "Parts de l'engranatge (disc, dents, eix), la construcció amb codi pas a pas i les variables d'enginyeria z i m (d = m · z). Explica per què dues rodes han de tenir el mateix mòdul i com es calcula la relació de transmissió.|Partes del engranaje (disco, dientes, eje), la construcción con código paso a paso y las variables de ingeniería z y m (d = m · z). Explica por qué dos ruedas tienen que tener el mismo módulo y cómo se calcula la relación de transmisión.",
        diu: ["Si poso més dents i no canvio el diàmetre, què passa amb les dents?|Si pongo más dientes y no cambio el diámetro, ¿qué pasa con los dientes?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: "Tot el grup|Todo el grupo" },
      { min: 8, t: "La fitxa d'especificacions|La ficha de especificaciones", fase: 'desconnectat', fa: "Per parelles: calculen amb la fitxa els diàmetres del pinyó i de la roda, la distància entre centres i la relació de transmissió, i dibuixen les dues circumferències primitives a escala 1:1 amb el compàs.|Por parejas: calculan con la ficha los diámetros del piñón y de la rueda, la distancia entre centros y la relación de transmisión, y dibujan las dos circunferencias primitivas a escala 1:1 con el compás.",
        diu: ["Quina distància hi ha entre els centres? Per què?|¿Qué distancia hay entre los centros? ¿Por qué?"], slides: ['s8'], app: "Encara no: fitxa, compàs i calculadora.|Todavía no: ficha, compás y calculadora.", org: "Per parelles|Por parejas" },
      { min: 20, t: "A l'ordinador: l'engranatge pas a pas|En el ordenador: el engranaje paso a paso", fase: 'ordinador', fa: "Fan l'app: la predicció paramètrica, els dos errors de la Nuvi (dents soltes i forat curt) i els quatre passos (dents, forat, paramètric i forats d'alleugeriment). Al pas 3, que canviïn z i m per comprovar que tot s'adapta. Qui acabi, fa les dues rodes que encaixen ⭐.|Hacen la app: la predicción paramétrica, los dos errores de la Nuvi (dientes sueltos y agujero corto) y los cuatro pasos (dientes, agujero, paramétrico y agujeros de aligeramiento). En el paso 3, que cambien z y m para comprobar que todo se adapta. Quien acabe, hace las dos ruedas que encajan ⭐.",
        diu: ["Quin número fix encara no és una variable?|¿Qué número fijo todavía no es una variable?", "Amb z = 20, quant fa el diàmetre exterior?|Con z = 20, ¿cuánto mide el diámetro exterior?"], slides: ['s9', 's10', 's11', 's12'], app: "Sessió «Projecte: l'engranatge», fins al projecte.|Sesión «Proyecto: el engranaje», hasta el proyecto.", org: "Individual|Individual" },
      { min: 14, t: "El meu engranatge per a l'autòmat|Mi engranaje para el autómata", fase: 'crea', fa: "Projecte: cada alumne/a tria z i m, completa el programa paramètric i hi afegeix un detall propi (maneta, forats d'alleugeriment, relleu…). Ha de funcionar amb z = 8 i z = 16. Es desa a «Projectes» amb l'STL. Al final, la fitxa tècnica a la llibreta.|Proyecto: cada alumno/a elige z y m, completa el programa paramétrico y le añade un detalle propio (mango, agujeros de aligeramiento, relieve…). Tiene que funcionar con z = 8 y z = 16. Se guarda en «Proyectos» con el STL. Al final, la ficha técnica en la libreta.",
        diu: ["Amb quina roda del company encaixaria el teu engranatge?|¿Con qué rueda del compañero encajaría tu engranaje?"], slides: ['s13'], app: "Pas «Projecte: el teu engranatge per a l'autòmat».|Paso «Proyecto: tu engranaje para el autómata».", org: "Individual|Individual" },
      { min: 5, t: "Tancament i fitxa tècnica|Cierre y ficha técnica", fase: 'tancament', fa: "Dos o tres alumnes presenten el seu engranatge: z, m, diàmetre exterior i detall propi. Tiquet de sortida.|Dos o tres alumnos presentan su engranaje: z, m, diámetro exterior y detalle propio. Ticket de salida.", diu: ["Un pinyó de 10 dents i una roda de 30: quina relació de transmissió tenen?|Un piñón de 10 dientes y una rueda de 30: ¿qué relación de transmisión tienen?"], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: "Tot el grup|Todo el grupo" }
    ],
    errors: [["Les dents queden soltes del disc.|Los dientes quedan sueltos del disco.", "Que compari on comença la dent amb el radi del disc: ha de començar una mica a dins (d / 2 − m). La comprovació «una sola peça» ho avisa.|Que compare dónde empieza el diente con el radio del disco: tiene que empezar un poco dentro (d / 2 − m). La comprobación «una sola pieza» lo avisa."],
      ["En canviar z, les dents se superposen o queden massa separades.|Al cambiar z, los dientes se superponen o quedan demasiado separados.", "Encara hi ha números fixos (30°, 36 mm…). Tot el que depèn de z s'ha d'escriure amb z: i * 360 / z, d = m * z i el bucle de 0 a (z - 1).|Todavía hay números fijos (30°, 36 mm…). Todo lo que depende de z tiene que escribirse con z: i * 360 / z, d = m * z y el bucle de 0 a (z - 1)."],
      ["El forat de l'eix no travessa.|El agujero del eje no atraviesa.", "El cilindre del forat ha de començar a z = −1 i fer h + 2: així sobresurt per dalt i per baix.|El cilindro del agujero tiene que empezar en z = −1 y medir h + 2: así sobresale por arriba y por abajo."]],
    diff: { mes: "Fer les dues rodes que encaixen ⭐ i calcular la relació de transmissió; després, pensar com es faria sense copiar codi (és el que veurem a la unitat de mòduls).|Hacer las dos ruedas que encajan ⭐ y calcular la relación de transmisión; después, pensar cómo se haría sin copiar código (es lo que veremos en la unidad de módulos).",
      menys: "Fer els passos 1 i 2 amb números fixos i, al pas 3, substituir les variables una a una, comprovant el model després de cada canvi. Al projecte, partir de l'engranatge del pas 3.|Hacer los pasos 1 y 2 con números fijos y, en el paso 3, sustituir las variables una a una, comprobando el modelo después de cada cambio. En el proyecto, partir del engranaje del paso 3." },
    aval: { ticket: ["Un pinyó de 10 dents mou una roda de 30. Quantes voltes fa la roda si el pinyó en fa 6?|Un piñón de 10 dientes mueve una rueda de 30. ¿Cuántas vueltas da la rueda si el piñón da 6?", "Per què dues rodes han de tenir el mateix mòdul?|¿Por qué dos ruedas tienen que tener el mismo módulo?"],
      rubric: [["Model de l'engranatge|Modelo del engranaje", "Disc, dents i forat ben fets: una sola peça amb el forat que travessa.|Disco, dientes y agujero bien hechos: una sola pieza con el agujero que atraviesa.", "Hi ha el disc i les dents, però amb peces soltes o el forat curt.|Están el disco y los dientes, pero con piezas sueltas o el agujero corto."],
        ["Disseny paramètric|Diseño paramétrico", "Funciona amb qualsevol z i m, i ho ha comprovat.|Funciona con cualquier z y m, y lo ha comprobado.", "Funciona amb el valor de partida o amb algun número fix.|Funciona con el valor de partida o con algún número fijo."],
        ["Enginyeria i documentació|Ingeniería y documentación", "Calcula diàmetres i relació de transmissió i ho documenta a la fitxa tècnica.|Calcula diámetros y relación de transmisión y lo documenta en la ficha técnica.", "Fa alguns càlculs amb ajuda; la fitxa està incompleta.|Hace algunos cálculos con ayuda; la ficha está incompleta."]] },
    casa: "Busca un mecanisme amb engranatges (una bicicleta, una batedora manual, un rellotge, una joguina). Compta les dents de dues rodes que encaixin i calcula la relació de transmissió.|Busca un mecanismo con engranajes (una bicicleta, una batidora manual, un reloj, un juguete). Cuenta los dientes de dos ruedas que encajen y calcula la relación de transmisión.",
    intro: "Projecte de la unitat: tot el que han après (bucles, patrons circulars, resta i variables) en una peça d'enginyeria real. Els engranatges reals tenen dents de perfil corbat (evolvent); aquí fem una aproximació amb caixes, que imprimida funciona en mecanismes senzills de cartró o fusta.|Proyecto de la unidad: todo lo que han aprendido (bucles, patrones circulares, resta y variables) en una pieza de ingeniería real. Los engranajes reales tienen dientes de perfil curvo (evolvente); aquí hacemos una aproximación con cajas, que impresa funciona en mecanismos sencillos de cartón o madera.",
    claus: ["Un engranatge és un disc, un patró circular de z dents i un forat d'eix fet amb resta.|Un engranaje es un disco, un patrón circular de z dientes y un agujero de eje hecho con resta.", "Les variables z i m fan el disseny paramètric: d = m · z i el diàmetre exterior és m · (z + 2).|Las variables z y m hacen el diseño paramétrico: d = m · z y el diámetro exterior es m · (z + 2).", "Dues rodes encaixen amb el mateix mòdul; la distància entre centres és (d1 + d2) / 2.|Dos ruedas encajan con el mismo módulo; la distancia entre centros es (d1 + d2) / 2.", "Relació de transmissió = z de la roda / z del pinyó.|Relación de transmisión = z de la rueda / z del piñón."],
    prev: ["Haver fet les tres sessions anteriors de la unitat (files, graelles i patrons circulars).|Haber hecho las tres sesiones anteriores de la unidad (filas, rejillas y patrones circulares).", "Conèixer resta i uneix (unitat 3) i les variables (unitat 4).|Conocer resta y une (unidad 3) y las variables (unidad 4).", "Saber fer servir el compàs i la calculadora.|Saber usar el compás y la calculadora."],
    faq: [["Els engranatges de veritat tenen les dents així, quadrades?|¿Los engranajes de verdad tienen los dientes así, cuadrados?", "No: tenen un perfil corbat (de «evolvent») perquè les dents rodolin sense xocar. Les nostres són una aproximació que funciona a poca velocitat; OpenSCAD té biblioteques que fan el perfil exacte.|No: tienen un perfil curvo (de «evolvente») para que los dientes rueden sin chocar. Los nuestros son una aproximación que funciona a poca velocidad; OpenSCAD tiene bibliotecas que hacen el perfil exacto."],
      ["Per què es diu z al nombre de dents?|¿Por qué se llama z al número de dientes?", "És la notació habitual a l'enginyeria mecànica i a les normes tècniques d'engranatges. Fer-la servir ens ajuda a llegir catàlegs i plànols.|Es la notación habitual en la ingeniería mecánica y en las normas técnicas de engranajes. Usarla nos ayuda a leer catálogos y planos."],
      ["Puc imprimir-lo i fer-lo girar de veritat?|¿Puedo imprimirlo y hacerlo girar de verdad?", "Sí: amb un eix de 6 mm (un llapis prim, una vareta o un cargol) i dues rodes del mateix mòdul. Deixeu una mica de joc a la distància entre centres (0,5 mm) perquè no s'encallin.|Sí: con un eje de 6 mm (un lápiz fino, una varilla o un tornillo) y dos ruedas del mismo módulo. Dejad un poco de juego en la distancia entre centros (0,5 mm) para que no se atasquen."]],
    tec: [["Amb z = 40 o més, el 3D va lent.|Con z = 40 o más, el 3D va lento.", "Són moltes peces dins d'una resta. Proveu amb z petits i feu la prova gran al final.|Son muchas piezas dentro de una resta. Probad con z pequeños y haced la prueba grande al final."],
      ["Surt «la variable z no existeix».|Sale «la variable z no existe».", "Les variables s'han de crear abans de fer-les servir: les línies z = …, m = … van al principi del programa.|Las variables tienen que crearse antes de usarlas: las líneas z = …, m = … van al principio del programa."],
      ["El botó de desar del projecte no s'activa.|El botón de guardar del proyecto no se activa.", "Mireu quina comprovació falta (en vermell). Sovint és «Funciona amb z = 8, 16»: canvieu z a mà per veure què falla.|Mirad qué comprobación falta (en rojo). A menudo es «Funciona con z = 8, 16»: cambiad z a mano para ver qué falla."]],
    extra: ["Fer un tren d'engranatges de tres rodes (8, 16 i 8) i calcular-ne la relació total.|Hacer un tren de engranajes de tres ruedas (8, 16 y 8) y calcular su relación total.", "Fer una cremallera: dents en fila (bucle de la sessió 1) amb el mateix mòdul.|Hacer una cremallera: dientes en fila (bucle de la sesión 1) con el mismo módulo.", "Exportar el .scad i comparar-lo amb una biblioteca d'engranatges d'OpenSCAD.|Exportar el .scad y compararlo con una biblioteca de engranajes de OpenSCAD."],
    trans: ["Unitat següent: mòduls, per no haver de copiar codi (com a les dues rodes).|Unidad siguiente: módulos, para no tener que copiar código (como en las dos ruedas).", "Tecnologia: mecanismes de transmissió del moviment (politges, engranatges, cadenes).|Tecnología: mecanismos de transmisión del movimiento (poleas, engranajes, cadenas)."],
    slides: [
      { id: 's1', k: 'portada', t: "Projecte: l'engranatge|Proyecto: el engranaje", x: "Un programa per a totes les rodes de l'autòmat|Un programa para todas las ruedas del autómata", nota: "Ensenya engranatges reals i l'autòmat, si en teniu.|Enseña engranajes reales y el autómata, si tenéis." },
      { id: 's2', k: 'pregunta', t: 'Quantes voltes?|¿Cuántas vueltas?', x: "Un pinyó de 8 dents mou una roda de 16. Quantes voltes fa el pinyó per cada volta de la roda?|Un piñón de 8 dientes mueve una rueda de 16. ¿Cuántas vueltas da el piñón por cada vuelta de la rueda?", nota: "Comproveu-ho amb engranatges de veritat: 2 voltes.|Comprobadlo con engranajes de verdad: 2 vueltas." },
      { id: 's3', k: 'anim', t: 'Dues rodes que encaixen|Dos ruedas que encajan', anim: 'p5gear', nota: "Fixeu-vos en el punt blanc de cada roda per comptar voltes.|Fijaos en el punto blanco de cada rueda para contar vueltas." },
      { id: 's4', k: 'media', t: 'Les dents: un patró circular|Los dientes: un patrón circular', media: { k: 'model', prog: GEARB }, nota: "La dent comença 3 mm dins del disc (15 < 18) i es centra amb −2,25.|El diente empieza 3 mm dentro del disco (15 < 18) y se centra con −2,25." },
      { id: 's5', k: 'media', t: "El forat de l'eix|El agujero del eje", media: { k: 'model', prog: GEAR12 }, nota: "resta { uneix { disc i dents } forat }. El forat sobresurt 1 mm per dalt i per baix.|resta { une { disco y dientes } agujero }. El agujero sobresale 1 mm por arriba y por abajo." },
      { id: 's6', k: 'media', t: 'z, m i d = m · z|z, m y d = m · z', media: { k: 'model', prog: GEARP }, nota: "Totes les mides depenen de z i m. Diàmetre exterior: m × (z + 2) = 42 mm.|Todas las medidas dependen de z y m. Diámetro exterior: m × (z + 2) = 42 mm." },
      { id: 's7', k: 'concepte', t: 'Enginyeria de les rodes|Ingeniería de las ruedas', punts: ["Mateix mòdul → les dents encaixen.|Mismo módulo → los dientes encajan.", "Distància entre centres = (d1 + d2) / 2.|Distancia entre centros = (d1 + d2) / 2.", "Relació de transmissió = z2 / z1.|Relación de transmisión = z2 / z1."], nota: "Pinyó 8 (d = 24) i roda 16 (d = 48): centres a 36 mm i relació 2.|Piñón 8 (d = 24) y rueda 16 (d = 48): centros a 36 mm y relación 2." },
      { id: 's8', k: 'activitat', t: "La fitxa d'especificacions|La ficha de especificaciones", timer: 7, punts: ["Calculeu d i el diàmetre exterior de cada roda.|Calculad d y el diámetro exterior de cada rueda.", "La distància entre centres.|La distancia entre centros.", "Dibuixeu-les a escala 1:1.|Dibujadlas a escala 1:1."], nota: "Per parelles, amb compàs i calculadora.|Por parejas, con compás y calculadora." },
      { id: 's9', k: 'repte', t: "A l'ordinador: pas a pas|En el ordenador: paso a paso", punts: ["1 · Les dents.|1 · Los dientes.", "2 · El forat de l'eix.|2 · El agujero del eje.", "3 · Paramètric.|3 · Paramétrico.", "4 · Més lleuger.|4 · Más ligero."], nota: "Al pas 3, que canviïn z i m i comprovin que tot s'adapta.|En el paso 3, que cambien z y m y comprueben que todo se adapta." },
      { id: 's10', k: 'concepte', t: 'Dels números a les variables|De los números a las variables', x: "Cada número fix que depèn de les dents es converteix en un càlcul amb z i m.|Cada número fijo que depende de los dientes se convierte en un cálculo con z y m.", code: CK(`repeteix i de 0 a (z - 1) {\n  gira(0, 0, i * 360 / z) mou(d / 2 - m, -m * 0.75, 0) cub(2 * m, 1.5 * m, h)\n}`), nota: "30° → 360 / z; 15 → d / 2 − m; 6 → 2 · m; 4,5 → 1,5 · m.|30° → 360 / z; 15 → d / 2 − m; 6 → 2 · m; 4,5 → 1,5 · m." },
      { id: 's11', k: 'media', t: "La roda de 20 dents|La rueda de 20 dientes", media: { k: 'model', prog: GEARP20 }, nota: "El mateix programa amb z = 20: d = 60 mm. Les dents són iguals que a la de 12.|El mismo programa con z = 20: d = 60 mm. Los dientes son iguales que en la de 12." },
      { id: 's12', k: 'media', t: 'Dues rodes que encaixen ⭐|Dos ruedas que encajan ⭐', media: { k: 'model', prog: TWO, view: 'top' }, nota: "La roda va girada 11,25° (mig pas) perquè una dent del pinyó entri en un buit.|La rueda va girada 11,25° (medio paso) para que un diente del piñón entre en un hueco." },
      { id: 's13', k: 'repte', t: 'El meu engranatge|Mi engranaje', punts: ["Variables z i m, i d = m · z.|Variables z y m, y d = m · z.", "Forat de l'eix que travessa.|Agujero del eje que atraviesa.", "Funciona amb z = 8 i z = 16.|Funciona con z = 8 y z = 16.", "Un detall propi.|Un detalle propio."], nota: "Es desa a «Projectes» amb l'STL i el .scad.|Se guarda en «Proyectos» con el STL y el .scad." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Un engranatge és un patró circular amb resta.|Un engranaje es un patrón circular con resta.", "z i m fan el disseny paramètric.|z y m hacen el diseño paramétrico.", "Relació de transmissió = z2 / z1.|Relación de transmisión = z2 / z1."], nota: "Llegiu-ho junts.|Leedlo juntos." },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Pinyó de 10 i roda de 30: si el pinyó fa 6 voltes, quantes en fa la roda?|Piñón de 10 y rueda de 30: si el piñón da 6 vueltas, ¿cuántas da la rueda?", "Per què el mateix mòdul?|¿Por qué el mismo módulo?"], nota: "En un paper, abans de sortir.|En un papel, antes de salir." }
    ],
    print: [{ id: 'p1', t: "Fitxa d'especificacions: l'engranatge|Ficha de especificaciones: el engranaje", k: 'fitxa', intro: "L'autòmat necessita un pinyó de 8 dents i una roda de 16, de mòdul m = 3, gruix 6 mm i eix de 6 mm. Fes els càlculs abans de modelar.|El autómata necesita un piñón de 8 dientes y una rueda de 16, de módulo m = 3, grosor 6 mm y eje de 6 mm. Haz los cálculos antes de modelar.",
      items: [{ q: "Diàmetre primitiu (d = m × z) i diàmetre exterior (m × (z + 2)) del pinyó i de la roda.|Diámetro primitivo (d = m × z) y diámetro exterior (m × (z + 2)) del piñón y de la rueda.", sol: "Pinyó: d = 24 mm, exterior 30 mm. Roda: d = 48 mm, exterior 54 mm.|Piñón: d = 24 mm, exterior 30 mm. Rueda: d = 48 mm, exterior 54 mm." },
        { q: "A quina distància han d'estar els dos centres? Dibuixa les dues circumferències primitives a escala 1:1, tocant-se.|¿A qué distancia tienen que estar los dos centros? Dibuja las dos circunferencias primitivas a escala 1:1, tocándose.", big: true, sol: "(24 + 48) / 2 = 36 mm. Radis de 12 i 24 mm.|(24 + 48) / 2 = 36 mm. Radios de 12 y 24 mm." },
        { q: "Relació de transmissió: si el pinyó fa 6 voltes, quantes en fa la roda? I si la roda en fa 5?|Relación de transmisión: si el piñón da 6 vueltas, ¿cuántas da la rueda? ¿Y si la rueda da 5?", sol: "Relació 16 / 8 = 2. Pinyó 6 voltes → roda 3. Roda 5 voltes → pinyó 10.|Relación 16 / 8 = 2. Piñón 6 vueltas → rueda 3. Rueda 5 vueltas → piñón 10." },
        { q: "Fitxa tècnica del teu engranatge: z, m, d, diàmetre exterior, gruix, eix, detall propi i amb quina roda encaixa.|Ficha técnica de tu engranaje: z, m, d, diámetro exterior, grosor, eje, detalle propio y con qué rueda encaja.", big: true, sol: "Resposta oberta. Comproveu que d = m × z i que la roda amb què encaixa té el mateix mòdul.|Respuesta abierta. Comprobad que d = m × z y que la rueda con la que encaja tiene el mismo módulo." }] }]
  }
  };
})());
